module.exports = [{"id":"m-for-daishu","title":"代数公式速查","subtitle":"速查 · 数与代数","grade":"all","tags":["公式与定理","数与代数"],"blocks":[{"type":"note","title":"教材章节","text":"速查 · 数与代数"},{"type":"note","title":"一句话概述","text":"整式乘法、幂的运算、因式分解、分式与二次根式的公式集中成一张卡，按「乘法公式 → 幂 → 因式分解 → 分式 → 根式」排列，考场 5 分钟过一遍。"},{"type":"h","text":"先看这批公式解决哪一类问题"},{"type":"p","text":"这张卡收的是「运算」类结论：整式乘法、幂的运算、因式分解、分式化简、二次根式化简，五类各有一套固定公式。做题时先给式子归类，再去对应区间取公式，比从第一行往下背快得多。"},{"type":"figure","figure":{"id":"fig-for-daishu-s1","title":"五类运算与对应公式的分区","caption":"先给式子归类，再取公式","view":"wide","alt":"五个并排的方框，依次标着整式乘法、幂的运算、因式分解、分式运算、二次根式，表示这张速查卡按运算类型分成五个区","prims":[{"t":"rect","x":2,"y":22,"w":18,"h":14,"tone":"main","label":"整式乘法"},{"t":"rect","x":21.5,"y":22,"w":18,"h":14,"tone":"main","label":"幂的运算"},{"t":"rect","x":41,"y":22,"w":18,"h":14,"tone":"main","label":"因式分解"},{"t":"rect","x":60.5,"y":22,"w":18,"h":14,"tone":"main","label":"分式运算"},{"t":"rect","x":80,"y":22,"w":18,"h":14,"tone":"main","label":"二次根式"},{"t":"text","x":50,"y":13,"text":"按运算类型分区取公式","size":3.6,"tone":"muted"}]}},{"type":"h","text":"平方差最容易被误用"},{"type":"p","text":"平方差公式 (a+b)(a-b)=a²-b² 要求两个括号里一个是「相同项」、另一个是「相反项」。对应到图形上，就是边长 a 的正方形挖掉角上边长 b 的小正方形，剩下的 L 形恰好能拼成 (a+b) 乘 (a-b) 的矩形。"},{"type":"figure","figure":{"id":"fig-for-daishu-s2","title":"平方差公式的面积示意","caption":"边长 a 的正方形挖去边长 b 的小正方形，余下的 L 形拼成矩形","view":"wide","alt":"左侧是边长 a 的正方形挖去右下角边长 b 的小正方形后剩下的 L 形，面积为 a 平方减 b 平方；右侧是一个长 a 加 b、宽 a 减 b 的矩形，两者面积相等","prims":[{"t":"poly","points":[[10,10],[50,10],[50,36],[36,36],[36,50],[10,50]],"closed":true,"tone":"main","fill":true},{"t":"rect","x":36,"y":36,"w":14,"h":14,"dashed":true,"tone":"muted"},{"t":"text","x":7,"y":33,"text":"a","size":4,"anchor":"end"},{"t":"text","x":30,"y":56,"text":"a","size":4},{"t":"text","x":43,"y":33.5,"text":"b","size":3.4,"tone":"muted"},{"t":"text","x":22,"y":25,"text":"a²−b²","size":3.6,"tone":"accent"},{"t":"text","x":55,"y":34,"text":"=","size":4.6},{"t":"rect","x":58,"y":22,"w":40,"h":20,"tone":"accent"},{"t":"text","x":78,"y":33,"text":"(a+b)(a−b)","size":4},{"t":"text","x":78,"y":18,"text":"a−b","size":3.6},{"t":"text","x":78,"y":47,"text":"a+b","size":3.6}]}},{"type":"h","text":"完全平方公式怎么变形"},{"type":"p","text":"完全平方公式 (a± b)²=a²±2ab+b² 的中间项系数是 2，不是 1。把拼图里的两块 ab 去掉，就得到变形 a²+b²=(a+b)²-2ab；已知 a+b、ab、a²+b² 中任意两个量，都能用这条变形求第三个。"},{"type":"figure","figure":{"id":"fig-for-daishu-s3","title":"完全平方公式的变形","caption":"从 (a+b)² 的拼图里去掉两块 ab，剩下 a²+b²","view":"square","alt":"边长为 a 加 b 的正方形分成四块：左上角是边长 a 的正方形 a 平方，右下角是边长 b 的正方形 b 平方，右上与左下两块都是长 a 宽 b 的矩形 ab；去掉两块 ab 后剩下 a 平方加 b 平方","prims":[{"t":"rect","x":15,"y":15,"w":45,"h":45,"tone":"main","fill":true,"label":"a²"},{"t":"rect","x":60,"y":15,"w":25,"h":45,"tone":"muted","fill":true,"dashed":true,"label":"ab"},{"t":"rect","x":15,"y":60,"w":45,"h":25,"tone":"muted","fill":true,"dashed":true,"label":"ab"},{"t":"rect","x":60,"y":60,"w":25,"h":25,"tone":"main","fill":true,"label":"b²"},{"t":"text","x":37,"y":12,"text":"a","size":4},{"t":"text","x":72,"y":12,"text":"b","size":4},{"t":"text","x":12,"y":38,"text":"a","size":4,"anchor":"end"},{"t":"text","x":12,"y":73,"text":"b","size":4,"anchor":"end"},{"t":"text","x":50,"y":93,"text":"a²+b²=(a+b)²−2ab","size":4.2,"tone":"accent"}]}},{"type":"h","text":"幂的三条规则别混用"},{"type":"p","text":"同底数幂相乘指数相加，幂的乘方指数相乘，积的乘方每个因式分别乘方：a^m· a^n=a^(m+n)、(a^m)^n=a^(mn)、(ab)^n=a^nb^n。题目给出两个量求第三个量时，先判断属于哪条规则，再代入变形，不要凭印象搬公式。"},{"type":"figure","figure":{"id":"fig-for-daishu-s4","title":"幂的三条运算规则","caption":"指数相加、指数相乘、分别乘方，三条各管一种结构","view":"wide","alt":"三个方框，分别写着同底数幂相乘对应指数相加、幂的乘方对应指数相乘、积的乘方对应各因式分别乘方","prims":[{"t":"rect","x":8,"y":12,"w":84,"h":12,"tone":"main","label":"同底数幂相乘 → 指数相加"},{"t":"rect","x":8,"y":28,"w":84,"h":12,"tone":"main","label":"幂的乘方 → 指数相乘"},{"t":"rect","x":8,"y":44,"w":84,"h":12,"tone":"main","label":"积的乘方 → 各因式分别乘方"}]}},{"type":"h","text":"核心概念"},{"type":"p","text":"本卡怎么用：整式、分式、二次根式三类运算的公式集中速查。按「两式相乘 → 幂的运算 → 因式分解 → 分式 → 根式」的顺序排布，做题时先判断运算类型，再在对应区间找公式。"},{"type":"p","text":"看到什么就找哪一条：见「两数和乘两数差」找平方差；见三项平方或题目给出 a+b、a-b、ab、a²+b² 中两个量，找完全平方公式的变形；见指数运算找幂的四条性质；见分式先想分式基本性质，见根号先看被开方数是否非负。"},{"type":"p","text":"带 ★ 的是必考：带 ★ 的条目是广州中考与各区模考的高频点：平方差公式、完全平方公式、幂的四条运算性质、零指数与负整数指数、提公因式与公式法分解因式、分式的基本性质与四则运算、二次根式的性质 √(a²)=|a|。"},{"type":"p","text":"两个前提不能忘：凡含分母的公式都要求分母不为 0；凡含偶次根号的式子都要求被开方数非负。这是填空题与化简题最常见的扣分点。"},{"type":"p","text":"结果要「收到最简」：整式乘法要合并同类项；因式分解要分解到每个因式都不能再分解；分式结果要化为最简分式或整式；根式结果要被开方数不含分母、不含能开得尽方的因数。"},{"type":"note","title":"中考考法","text":"乘法公式与幂运算的混合化简\n选择题辨运算正误、解答题考整式化简，平方差、完全平方与幂的四条性质常组合出现，中间项系数 2 和指数加减乘是主要扣分点。"},{"type":"note","title":"中考考法","text":"因式分解的顺序与彻底性\n解答题要求先提公因式再用公式，分解到每个因式都不能再分解，只分解一步或没写成乘积形式都会失分。"},{"type":"note","title":"中考考法","text":"分式与二次根式的化简求值\n中考常考先化简再代入求值，分式要约成最简，根式化到被开方数不含分母和开得尽的因数，代入前先看字母取值是否使式子有意义。"},{"type":"note","title":"中考考法","text":"零指数、负整数指数与有意义条件\n选择题常考 a⁰=1 的前提和负指数取倒数，凡含分母或偶次根号的式子都要先写取值限制，这是填空高频陷阱。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["平方差公式 ★","两个数的和与这两个数的差的积，等于这两个数的平方差。","对任意实数、整式都成立。关键是先凑出「相同项与相反项」的结构：(-3+a)(-3-a) 中相同项是 -3、相反项是 a，结果是 (-3)²-a²=9-a²，即「相同项的平方减相反项的平方」。"],["完全平方公式 ★","两数和（差）的平方，等于它们的平方和加上（减去）它们积的 2 倍。","中间项系数是 2 而不是 1，符号与括号内的符号一致；(a-b)²=(b-a)² 恒成立，但 (a-b)³=-(b-a)³，奇次方不能交换。"],["完全平方公式的常用变形 ★","已知和、差、积、平方和中的两个量，求其余量时用变形公式。","常见考法：「已知 a+b=5，ab=6，求 a²+b²」直接套第一条得 25-12=13。注意 (a+b)² 与 (a-b)² 相差 4ab，不是 2ab。"],["三项完全平方公式","三项和的平方，等于各项的平方和加上每两项乘积的 2 倍。","交叉项共有三项，每项系数都是 2，符号由对应两项符号的乘积决定，如 (a-b+c)²=a²+b²+c²-2ab+2ac-2bc。漏掉交叉项或写错符号是最常见的错误。"],["同底数幂相乘 ★","同底数幂相乘，底数不变，指数相加。","底数必须完全相同才能用；指数相加不是相乘。底数可以是整式，如 (x+y)²·(x+y)³=(x+y)⁵；a²+a³ 是加法，不能合并成 a⁵。"],["同底数幂相除 ★","同底数幂相除，底数不变，指数相减。","这里 m、n 为正整数，底数必须 a≠ 0（否则无意义）。m>n 时结果是整式，m=n 时结果等于 a⁰=1，m<n 时结果是含负指数的分式形式。"],["幂的乘方 ★","幂的乘方，底数不变，指数相乘。","与同底数幂相乘（指数相加）严格区分：(a²)³=a⁶，而 a²· a³=a⁵；(a²)³≠ a²· a³。"],["积的乘方 ★","积的乘方，等于把积的每一个因式分别乘方，再把所得的幂相乘。","每个因式都要乘方，如 (2x)³=8x³，漏掉系数 2 是常见错误。公式可反向用于简算：(0.125)¹⁰·8¹⁰=(0.125×8)¹⁰=1；符号规律 (-ab)²=a²b²，(-ab)³=-a³b³。"],["零指数幂 ★","任何不等于 0 的数的 0 次幂都等于 1。","条件 a≠0 是必考陷阱，0⁰ 无意义。底数只要是「非零」即可，如 (-3)⁰=1，(π-3.14)⁰=1，(x-1)⁰ 有意义的条件是 x≠1。"],["负整数指数幂 ★","一个数的负整数次幂（n 为正整数），等于这个数的正整数次幂的倒数。","公式中的 n 为正整数，底数必须 a≠0。负指数表示「取倒数」，不是「负数」：2^(-3)=(1)/(8)。分式的负指数直接把分子分母颠倒：((2)/(3))^(-2)=((3)/(2))²=(9)/(4)。"],["提公因式法分解因式 ★","如果多项式的各项含有公因式，把它提出来，变成两个因式的积。","公因式取「各项系数绝对值的最大公约数」与「各项都含有的字母的最低次幂」的积；提完后括号内的项数必须与原多项式项数相同（某项被全部提走时括号里要留下 1，如 m²+m=m(m+1)）。分解因式时要先提公因式，再考虑公式法。"],["公式法分解因式 ★","两项作差用平方差公式；三项且首末两项为平方、中间项是首末两项底数积的 2 倍时用完全平方公式。","分解必须彻底：x⁴-1=(x²+1)(x²-1)=(x²+1)(x+1)(x-1)，停在前一步不给满分；和的平方项 a²+b² 在实数范围内不能分解，不要写成 (a+b)²。"],["十字相乘法（二次三项式）★","常数项分解为两数之积，若这两数之和恰好等于一次项系数，则可分解为 (x+p)(x+q)。","适用于首项系数为 1 的二次三项式，试算时看两个数「积为常数项、和为一次项系数」，符号口诀「同号取同、异号取绝对值大的那个的符号」。ax²+bx+c（a≠1）需要把首项系数也拆开做十字相乘，或先用公式法求根再写成 a(x-x₁)(x-x₂)。"],["立方和与立方差公式","两数的立方和（差），等于两数和（差）乘以它们的平方和与积的差（和）。","括号内的中间项符号与括号外的符号相反（和配减、差配加），且中间项是 ab 而不是 2ab。属拓展内容（教材不作必考要求），在化简求值与因式分解压轴题中常用。"],["完全立方公式","两数和（差）的立方，等于两数的立方和（差）与三项交叉项的和。","系数按 1,3,3,1 排列，符号随 b 的符号交替（(a-b)³=a³-3a²b+3ab²-b³）。属拓展结论，多用于化简与检验因式分解的结果。"],["分式的基本性质 ★","分式的分子与分母同乘（或除以）一个不等于 0 的整式，分式的值不变。","这是约分与通分的依据，M≠0 不可省略，且分式本身要求 B≠0。约分必须先分解因式，再约去公因式；不能只约去分子分母中的某一项，如 (x+1)/(x+2) 中的 x 不能约掉。"],["分式的乘除 ★","分式相乘，分子乘分子、分母乘分母；分式相除，把除式的分子分母颠倒后与被除式相乘。","条件是各分母不为 0（作除式时分母也不能为 0）。除法要先变乘法、再取倒数，取倒数的是除式整体；能分解因式的先分解再约分，结果必须是最简分式或整式。"],["分式的加减 ★","同分母分式相加减，分母不变、分子相加减；异分母分式先通分再加减。","同分母相减时分子要加括号，如 (x+1)/(x)-(3)/(x)=(x-2)/(x) 不能写成 x+1-3 丢括号。异分母取最简公分母（各分母所有因式的最高次幂之积），例：(1)/(x-1)+(1)/(x+1)=(2x)/(x²-1)。"],["二次根式的性质 ★","非负数的算术平方根的平方等于它本身；一个数的平方的算术平方根等于这个数的绝对值。","√(a²)=|a|，不是 a：√((-3)²)=3。√(a²)=a 只在 a≥0 时成立。√(a) 有意义的条件是 a≥0；√(a) 本身的值永远非负，所以 √(4)=2 只有一个值，不要写成 ±2。"],["二次根式的乘除与分母有理化 ★","二次根式相乘除，把被开方数相乘除；分母含根号时，分子分母同乘适当的因式使分母不含根号。","乘除的条件是被开方数非负（作除式时分母被开方数大于 0）。分母有理化利用平方差公式构造有理因式（如 √(a)+√(b) 乘 √(a)-√(b)，此时 a≠ b）；化简结果要求被开方数不含分母、不含能开得尽方的因数，如 √(12)=2√(3)。"]]},{"type":"note","title":"例题","text":"计算 (2x+3y)(2x-3y)-(x+2y)²。"},{"type":"figure","figure":{"id":"fig-m-for-daishu-1","title":"平方差公式的面积示意","caption":"边长 a 的大正方形去掉角上边长 b 的小正方形，余下 L 形可拼成 (a+b)(a−b) 的矩形","view":"wide","alt":"左侧是边长为 a 的大正方形，右下角挖去一个边长为 b 的小正方形，余下的 L 形面积为 a 平方减 b 平方；右侧是一个长为 a 加 b、宽为 a 减 b 的矩形，面积为两数和与两数差的积，两者面积相等","prims":[{"t":"rect","x":10,"y":13,"w":36,"h":36},{"t":"rect","x":33,"y":36,"w":13,"h":13,"fill":true,"dashed":true,"tone":"muted"},{"t":"text","x":6.5,"y":33,"text":"a","size":3.6,"anchor":"end"},{"t":"text","x":28,"y":53.5,"text":"a","size":3.6,"anchor":"middle"},{"t":"text","x":50,"y":44.5,"text":"b","size":3.6,"anchor":"start"},{"t":"text","x":39.5,"y":53.5,"text":"b","size":3.6,"anchor":"middle"},{"t":"text","x":21,"y":28,"text":"a²−b²","size":3.6,"anchor":"middle","tone":"accent"},{"t":"text","x":53,"y":34,"text":"=","size":4,"anchor":"middle"},{"t":"rect","x":57,"y":26,"w":38,"h":18},{"t":"text","x":76,"y":37,"text":"(a+b)(a−b)","size":3.4,"anchor":"middle"},{"t":"text","x":76,"y":53.5,"text":"a+b","size":3.6,"anchor":"middle"},{"t":"text","x":98,"y":37.5,"text":"a−b","size":3.6,"anchor":"start"}]}},{"type":"list","title":"解题步骤","items":["第一步定位公式：(2x+3y)(2x-3y) 中相同项是 2x、相反项是 3y，用平方差公式，得 (2x)²-(3y)²=4x²-9y²。","第二步用完全平方公式：(x+2y)²=x²+2· x·2y+(2y)²=x²+4xy+4y²。","第三步作差，括号前是负号，去括号时每一项都变号：4x²-9y²-x²-4xy-4y²。","第四步合并同类项：3x²-4xy-13y²。"]},{"type":"p","text":"答案：3x²-4xy-13y²"},{"type":"note","title":"方法小结","text":"先认「结构」再套公式，是这张卡最重要的用法：同样两个括号相乘，只有凑出「相同项与相反项」才能用平方差。去括号、合并同类项这两步决定正确率，负号要逐项处理。"},{"type":"note","title":"例题","text":"计算 (-1)²⁰²⁶+((1)/(3))^(-2)-(π-3)⁰+2^(-1)。"},{"type":"figure","figure":{"id":"fig-for-daishu-e2","title":"逐项算幂","caption":"负指数取倒数、非零数的零次幂为 1","view":"wide","alt":"四个方框列出各幂的值：负一的 2026 次幂为 1，三分之一的负二次幂为 9，π 减 3 的零次幂为 1，二的负一次幂为二分之一","prims":[{"t":"rect","x":6,"y":12,"w":40,"h":14,"tone":"main","label":"(−1)²⁰²⁶ = 1"},{"t":"rect","x":54,"y":12,"w":40,"h":14,"tone":"accent","label":"(1/3)⁻² = 9"},{"t":"rect","x":6,"y":34,"w":40,"h":14,"tone":"accent","label":"(π−3)⁰ = 1"},{"t":"rect","x":54,"y":34,"w":40,"h":14,"tone":"accent","label":"2⁻¹ = 1/2"},{"t":"text","x":50,"y":56,"text":"先逐项算幂，再合并","size":3.6,"tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["逐项求值：(-1)²⁰²⁶ 中指数为偶数，结果为 1。","由负整数指数幂的意义：((1)/(3))^(-2)=3²=9。","由零指数幂的意义：π-3≠ 0，所以 (π-3)⁰=1；2^(-1)=(1)/(2)。","合并结果：1+9-1+(1)/(2)=9+(1)/(2)=(19)/(2)。"]},{"type":"p","text":"答案：(19)/(2)"},{"type":"note","title":"方法小结","text":"实数混合运算先分项算幂：负指数变正指数的倒数、非零数的零次幂得 1，再按有理数法则合并；遇到 (π-a)⁰ 要先确认底数不为 0。"},{"type":"note","title":"例题","text":"先化简，再求值：(x-2)²-(x+3)(x-3)+x，其中 x=-2。"},{"type":"figure","figure":{"id":"fig-for-daishu-e3","title":"先展开、再合并、最后代入","caption":"两个公式各自展开后合并同类项，化简到最简式再代入","view":"wide","alt":"两个方框分别把 (x−2) 的平方展开为 x 平方减 4x 加 4、把 (x+3)(x−3) 展开为 x 平方减 9，两个结果合并后得到负 3x 加 13","prims":[{"t":"rect","x":4,"y":14,"w":26,"h":13,"tone":"main","label":"(x−2)²"},{"t":"arrow","x1":30.5,"y1":20.5,"x2":35.5,"y2":20.5},{"t":"rect","x":36,"y":14,"w":28,"h":13,"tone":"accent","label":"x²−4x+4"},{"t":"rect","x":4,"y":34,"w":26,"h":13,"tone":"main","label":"(x+3)(x−3)"},{"t":"arrow","x1":30.5,"y1":40.5,"x2":35.5,"y2":40.5},{"t":"rect","x":36,"y":34,"w":28,"h":13,"tone":"accent","label":"x²−9"},{"t":"arrow","x1":64.5,"y1":20.5,"x2":73.5,"y2":26},{"t":"arrow","x1":64.5,"y1":40.5,"x2":73.5,"y2":35},{"t":"rect","x":74,"y":24,"w":22,"h":15,"tone":"main","fill":true,"label":"−3x+13"},{"t":"text","x":50,"y":56,"text":"合并同类项后代入 x=−2","size":3.4,"tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["用完全平方公式展开：(x-2)²=x²-4x+4。","用平方差公式展开：(x+3)(x-3)=x²-9。","代入原式并去括号合并：x²-4x+4-(x²-9)+x=x²-4x+4-x²+9+x=-3x+13。","把 x=-2 代入：-3×(-2)+13=6+13=19。"]},{"type":"p","text":"答案：化简结果为 -3x+13；当 x=-2 时，原式的值为 19。"},{"type":"note","title":"方法小结","text":"化简求值题必须先化简到最简式再代入，直接把 x=-2 代入原式容易在平方和符号上出错；括号前是负号时，去括号每一项都要变号。"},{"type":"list","title":"易错点","items":["把 $(a+b)^2$ 写成 $a^2+b^2$，漏掉中间项；完全平方公式的中间项系数是 $2$，不是 $1$。","幂的运算混用：$a^2\\cdot a^3=a^5$（指数相加），$(a^2)^3=a^6$（指数相乘），$a^2+a^3$ 不能合并。","因式分解不彻底或结果没写成乘积形式：$x^4-1$ 只分解到 $(x^2+1)(x^2-1)$ 就停手，应继续分解为 $(x^2+1)(x+1)(x-1)$。","忽略条件：把 $\\sqrt{a^2}$ 写成 $a$；约分时把分子分母中的某一项直接约去（如 $\\frac{x+1}{x+2}$ 中的 $x$）；忘记 $a^0=1$ 要求 $a\\neq0$。"]},{"type":"list","title":"解题方法","items":["按运算对象分行记忆：乘法公式（平方差、完全平方、三项完全平方）→ 幂的四条性质 → 因式分解的三条路（提公因式、公式法、十字相乘）→ 分式基本性质与四则运算 → 二次根式性质与化简。","看到 a+b、a-b、ab、a²+b² 这四个量中的任意两个，第一反应就是完全平方公式的变形，这是化简求值题的通用突破口。","结果自检：整式乘法可用因式分解反验（4x²-9y² 应能分解回 (2x+3y)(2x-3y)）；分式与根式的结果看是否已化到最简，这是「过程对但没化到最简」类失分的最后一道防线。"]}],"questions":[{"id":"q-m-for-daishu-1","type":"choice","stem":"下列运算正确的是","answer":"B","explain":"完全平方公式为 (a± b)²=a²±2ab+b²，中间项是两数积的 2 倍，故 B 正确。A、D 都漏掉了完整的中间项 2ab；C 是平方差公式，结果应为 a²-b²。","options":["(a+b)²=a²+b²","(a-b)²=a²-2ab+b²","(a+b)(a-b)=a²+b²","(a+b)²=a²+ab+b²"],"difficulty":1,"tags":["乘法公式","完全平方公式"]},{"id":"q-m-for-daishu-2","type":"fill","stem":"已知 a+b=5，ab=6，则 a²+b² 的值是____。","answer":"13","explain":"由完全平方公式的变形 a²+b²=(a+b)²-2ab=25-12=13。若直接解方程组也可得 a=2,b=3 或 a=3,b=2，结果相同。","difficulty":2,"tags":["乘法公式","公式变形"]},{"id":"q-m-for-daishu-3","type":"choice","stem":"计算 (-2a²)³ 的结果是","answer":"B","explain":"由积的乘方 (ab)^n=a^nb^n 与幂的乘方 (a^m)^n=a^(mn)：(-2a²)³=(-2)³·(a²)³=-8a⁶。A 漏乘系数、把 (-2)³ 算成 -6；D 把指数乘方错当成相加。","options":["-6a⁶","-8a⁶","8a⁶","-8a⁵"],"difficulty":2,"tags":["幂的运算","积的乘方"]},{"id":"q-m-for-daishu-4","type":"short","stem":"把 x³-4x 分解因式，并说明每一步用到的方法。","answer":"$x^3-4x=x(x^2-4)=x(x+2)(x-2)$。第一步提公因式 $x$，第二步对 $x^2-4$ 使用平方差公式。","explain":"因式分解的顺序是「先提公因式，再用公式法」。x³-4x 的公因式是 x，提出后括号内 x²-4 是两项作差、且都是平方项，恰合平方差公式；分解到 x(x+2)(x-2) 时每个因式都是一次式，不能再分解，结果最简。","difficulty":2,"tags":["因式分解","平方差公式"],"rubric":["先提公因式 x，得 x(x²-4)","对 x²-4 使用平方差公式，得 (x+2)(x-2)","结果写成乘积形式 x(x+2)(x-2)，且每个因式都不能再分解","说明所用方法（提公因式法、公式法），顺序正确"]},{"id":"q-m-for-daishu-z1","type":"choice","stem":"下列因式分解正确的是","answer":"D","explain":"D 先提公因式 2 得 2(x²-4)，再用平方差公式分解为 2(x+2)(x-2)，分解彻底，正确。A 把平方差误写成完全平方，应为 (x+2)(x-2)；B 左边不是完全平方式，等号不成立；C 只分解了一步，括号内还能继续分解，应写成 x(x+1)(x-1)。","options":["x²-4=(x-2)²","x²+2x-1=(x-1)²","x³-x=x(x²-1)","2x²-8=2(x+2)(x-2)"],"difficulty":2,"tags":["因式分解","公式法"]},{"id":"q-m-for-daishu-z2","type":"fill","stem":"计算 √(12)-√(3) 的结果是____。","answer":"\\sqrt{3}|√3","explain":"先把 √(12) 化为最简二次根式：√(12)=√(4× 3)=2√(3)，再合并同类二次根式：2√(3)-√(3)=√(3)。被开方数含能开得尽方的因数时必须先化简。","difficulty":2,"tags":["二次根式","二次根式化简"]}]},{"id":"m-for-fangcheng","title":"方程与不等式速查","subtitle":"速查 · 方程与不等式","grade":"all","tags":["公式与定理","方程与不等式"],"blocks":[{"type":"note","title":"教材章节","text":"速查 · 方程与不等式"},{"type":"note","title":"一句话概述","text":"一元一次方程、二元一次方程组、一元二次方程与不等式（组）的解法步骤和结论集中速查，重点是求根公式、判别式、韦达定理与不等号变号。"},{"type":"h","text":"先看这批公式解决哪一类问题"},{"type":"p","text":"这张卡按方程类型分区：一元一次方程、二元一次方程组、一元二次方程、分式方程、不等式与不等式组。解方程类题目先给方程归类型，再照对应步骤走，最后一步永远是检验。"},{"type":"figure","figure":{"id":"fig-for-fangcheng-s1","title":"五类方程与不等式","caption":"先给方程归类型，再照对应步骤走","view":"wide","alt":"五个方框分别标着一元一次方程、二元一次方程组、一元二次方程、分式方程、不等式与不等式组，表示这张卡按方程类型分区","prims":[{"t":"rect","x":4,"y":8,"w":44,"h":13,"tone":"main","label":"一元一次方程"},{"t":"rect","x":52,"y":8,"w":44,"h":13,"tone":"main","label":"二元一次方程组"},{"t":"rect","x":4,"y":26,"w":44,"h":13,"tone":"main","label":"一元二次方程"},{"t":"rect","x":52,"y":26,"w":44,"h":13,"tone":"main","label":"分式方程"},{"t":"rect","x":4,"y":44,"w":92,"h":13,"tone":"main","label":"不等式与不等式组"}]}},{"type":"h","text":"判别式决定抛物线与 x 轴的交点个数"},{"type":"p","text":"判别式 Δ=b²-4ac 是「方程有几个实数根」的开关：Δ>0 有两个不等实根，Δ=0 有两个相等实根，Δ<0 无实数根。把二次方程看成一个二次函数，这三种情况恰好对应抛物线与 x 轴交点的个数，数形一对照就不会记混。"},{"type":"figure","figure":{"id":"fig-for-fangcheng-s2","title":"判别式与抛物线和 x 轴的位置","caption":"Δ<0 无交点、Δ=0 一个交点、Δ>0 两个交点","view":"tall","alt":"三个开口向上的抛物线并排画在同一条水平轴上方：左边一个整体在轴上方、与轴无交点；中间一个顶点恰好落在轴上、与轴只有一个交点；右边一个穿过轴、与轴有两个交点","prims":[{"t":"line","x1":6,"y1":110,"x2":94,"y2":110,"tone":"main"},{"t":"text","x":20,"y":18,"text":"Δ<0：无交点","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":18,"text":"Δ=0：一个交点","size":3.6,"tone":"muted"},{"t":"text","x":80,"y":18,"text":"Δ>0：两个交点","size":3.6,"tone":"muted"},{"t":"curve","points":[[7,93.8],[10,80],[13,69.8],[16,63.2],[20,60],[24,63.2],[27,69.8],[30,80],[33,93.8]],"tone":"accent"},{"t":"curve","points":[[38,135.9],[40,128],[43,118.8],[46,112.9],[50,110],[54,112.9],[57,118.8],[60,128],[62,135.9]],"tone":"accent"},{"t":"curve","points":[[72,124],[74,110],[76,100],[78,94],[80,92],[82,94],[84,100],[86,110],[88,124]],"tone":"accent"},{"t":"dot","x":74,"y":110,"r":1.4,"tone":"accent"},{"t":"dot","x":86,"y":110,"r":1.4,"tone":"accent"}]}},{"type":"h","text":"用韦达定理前先验判别式"},{"type":"p","text":"韦达定理 x₁+x₂=-(b)/(a)、x₁x₂=(c)/(a) 只在方程确实有实数根时才成立，所以用之前必须先算 Δ≥0。两根的和带负号、积不带负号，这两个符号是本条最容易写反的地方。"},{"type":"figure","figure":{"id":"fig-for-fangcheng-s3","title":"根与系数的关系","caption":"两根之和是一次项系数除以二次项系数的相反数","view":"wide","alt":"两个方框写着韦达定理：两根之和等于负 a 分之 b，两根之积等于 a 分之 c，并注明前提是判别式大于等于零","prims":[{"t":"rect","x":10,"y":12,"w":80,"h":12,"tone":"main","label":"x₁+x₂ = −b/a"},{"t":"rect","x":10,"y":28,"w":80,"h":12,"tone":"accent","label":"x₁x₂ = c/a"},{"t":"text","x":50,"y":50,"text":"前提：Δ ≥ 0","size":3.6,"tone":"muted"}]}},{"type":"h","text":"换个题型：分式方程为什么必须检验"},{"type":"p","text":"解分式方程的关键动作是「去分母」，两边同乘的是含未知数的整式，这个整式可能为 0，所以求出的根要代回最简公分母检验：不为 0 才是原方程的根，为 0 就是增根、必须舍去。换个题型也一样——只要两边同乘过含未知数的式子，就一定要检验。"},{"type":"figure","figure":{"id":"fig-for-fangcheng-s4","title":"解分式方程：一乘、二解、三检验","caption":"检验这一步是采分点，不能省","view":"wide","alt":"一个流程：先去分母化为整式方程并求解，再把根代入最简公分母检验，不为零则保留、为零则是增根必须舍去","prims":[{"t":"rect","x":8,"y":8,"w":36,"h":11,"tone":"main","label":"去分母 → 整式方程"},{"t":"arrow","x1":44.5,"y1":13.5,"x2":49.5,"y2":13.5},{"t":"rect","x":50,"y":8,"w":42,"h":11,"tone":"main","label":"解整式方程"},{"t":"arrow","x1":71,"y1":19.5,"x2":71,"y2":24},{"t":"rect","x":36,"y":24,"w":50,"h":11,"tone":"accent","label":"代入最简公分母检验"},{"t":"arrow","x1":50,"y1":35.5,"x2":30,"y2":40},{"t":"arrow","x1":70,"y1":35.5,"x2":72,"y2":40},{"t":"rect","x":8,"y":40,"w":42,"h":11,"tone":"ok","label":"≠0：保留"},{"t":"rect","x":52,"y":40,"w":42,"h":11,"tone":"danger","label":"=0：增根，舍去"}]}},{"type":"h","text":"核心概念"},{"type":"p","text":"本卡怎么用：按「一元一次方程 → 二元一次方程组 → 一元二次方程 → 分式方程 → 不等式与不等式组」的顺序排布。解方程类题目先看方程类型，再照对应步骤走，最后一步永远是检验。"},{"type":"p","text":"看到什么就找哪一条：要判断根的个数找判别式 Δ=b²-4ac；要算两根的和、积或它们的对称式找韦达定理；方程一边是平方形式（如 (x-1)²=9）用直接开平方法；含未知数的分母先找最简公分母并准备验根。"},{"type":"p","text":"带 ★ 的是必考：带 ★ 的条目是高频点：求根公式、判别式的三种情况、韦达定理、因式分解法解一元二次方程、分式方程的增根检验、不等式两边同乘负数要变号、不等式组解集的四种情况。"},{"type":"p","text":"两个「必须写出来」的动作：解分式方程必须写出「检验」（代入最简公分母，判断是否为 0）；含参数的一元二次方程必须先讨论二次项系数是否为 0、并检验 Δ≥0。这两处不写就是按步扣分。"},{"type":"note","title":"中考考法","text":"判别式与韦达定理的应用\n选择填空高频：由 Δ 判根的个数、由韦达定理求两根的对称式，含参数题先讨论二次项系数，用韦达定理前确认 Δ≥0。"},{"type":"note","title":"中考考法","text":"一元二次方程的实际应用\n增长率、利润、面积问题是解答题常客，平均增长率列 a(1± x)²=b，解出后按实际意义舍去负根和不合题意的根。"},{"type":"note","title":"中考考法","text":"分式方程的解法与增根\n解答题必须写出去分母、求解、检验三步，根使最简公分母为 0 即增根须舍去，求参数时常由增根反代整式方程。"},{"type":"note","title":"中考考法","text":"不等式变号与不等式组的解集\n两边同乘或除以负数必变号是必考陷阱，不等式组解集画数轴确定，端点能否取等要代回边界逐一核对。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["一元一次方程的一般形式与解","只含一个未知数、未知数的次数是 1、等号两边都是整式的方程叫一元一次方程。","a≠0 是一元一次方程定义的一部分。含字母系数时要讨论：a≠0 时方程有唯一解 x=-(b)/(a)；a=0 且 b≠0 时无解；a=0 且 b=0 时任意实数都是解。"],["解一元一次方程的步骤","去分母 → 去括号 → 移项 → 合并同类项 → 系数化为 1。","去分母时每一项都要乘最简公分母，不含分母的项最容易漏乘；分子是多项式时先去括号要加括号。移项必须变号。系数化为 1 时两边同除以未知数的系数，系数为负时要连同符号一起除。"],["等式的性质","等式两边加（减）同一个数或同一个整式，结果仍相等；等式两边乘同一个数，结果仍相等；等式两边除以同一个不为 0 的数，结果仍相等。","两边同除以一个式子时，必须保证这个式子不为 0；等式两边不能随意平方或开方（可能产生增根或丢根）。"],["二元一次方程组的解法：代入消元法","把一个方程变形为「用一个未知数表示另一个未知数」，代入另一个方程，消去一个未知数，化为一元一次方程求解。","变形时挑选系数简单的方程（系数为 1 或 -1 的最好）；求出一个未知数后，代回原方程组中较简单的方程求另一个；最后要把解写成用大括号括起来的方程组的形式，不要只写一个值。"],["二元一次方程组的解法：加减消元法","把一个（或两个）方程的两边同乘适当的数，使某个未知数的系数相等或互为相反数，再把两个方程相减或相加，消去这个未知数。","系数互为相反数时用加法，系数相等时用减法；做减法时被减方程的每一项都要变号，这是最容易错的一步。乘数时要乘遍方程中的每一项（含等号右边的常数）。"],["一元二次方程的一般形式","只含一个未知数、未知数的最高次数是 2 的整式方程叫一元二次方程。","代入求根公式前必须先把方程整理成一般形式（右边为 0、按 x 的降幂排列），才能正确读出 a、b、c。a≠0 是定义的一部分，含字母系数时一定要先讨论 a 是否为 0。"],["直接开平方法","形如 x²=p（p≥0）或 (mx+n)²=p（p≥0）的方程，两边直接开平方求解。","开平方时右边要同时取正、负两个值（x=±√(p)）；p<0 时方程无实数根。p=0 时两个根相等，即 x₁=x₂=0。"],["配方法","把方程的一边配成完全平方式，另一边是一个常数，再用直接开平方法求解。","二次项系数不为 1 时，先两边同除以二次项系数。配方时加上再减去「一次项系数一半的平方」，保持恒等。配方后右边为负数说明无实数根（等价于 Δ<0）。"],["一元二次方程的求根公式 ★","把一般形式 ax²+bx+c=0 的系数代入公式即可求根。","使用前提是 b²-4ac≥0；分母是 2a 而不是 a（整条公式都要除以 2a）；b 本身带符号，如 x²-3x+1=0 中 b=-3，公式里的 -b=3。先算 Δ 再代入，可以避免算到一半才发现无实根。"],["根的判别式 ★","Δ>0 时方程有两个不相等的实数根；Δ=0 时有两个相等的实数根；Δ<0 时没有实数根。","判别式只对方程的一般形式（a≠0）有效，使用前必须先化成一般式。文字表述要分清：「有两个实数根」对应 Δ≥0，「有两个相等的实数根」对应 Δ=0，含参数题必须按这三种情况分类讨论。"],["根与系数的关系（韦达定理）★","若 x₁、x₂ 是一元二次方程 ax²+bx+c=0 的两个根，则两根之和等于一次项系数除以二次项系数的相反数，两根之积等于常数项除以二次项系数。","前提是 Δ≥0（方程确实有实数根），用前先检验。一次项系数前有负号，x₁+x₂ 是 -(b)/(a) 而不是 (b)/(a)。常用变形：x₁²+x₂²=(x₁+x₂)²-2x₁x₂，(1)/(x₁)+(1)/(x₂)=(x₁+x₂)/(x₁x₂)，(x₁-x₂)²=(x₁+x₂)²-4x₁x₂。"],["因式分解法解一元二次方程 ★","把方程的一边化为 0，另一边分解成两个一次因式的积，由 AB=0 得到 A=0 或 B=0，从而求出两根。","右边必须化为 0 才能用（如 x²=3x 要先移项得 x²-3x=0）。绝对不能两边同时约去含未知数的因式，否则会丢掉一个根：x²=3x 的根是 x₁=0、x₂=3，写成 x=3 就丢根了。"],["一元二次方程四种解法的选用","形如 (mx+n)²=p 用直接开平方法；二次项系数为 1 且一次项系数为偶数用配方法；一般情形用公式法；左边容易分解因式的用因式分解法。","公式法最通用但计算量最大；因式分解法最快，但只适用于能分解的方程。做题顺序建议：先看能否直接开平方，再看能否因式分解，都不行才用公式法（配方法主要用于推导公式和求最值）。"],["分式方程的解法与增根检验 ★","去分母（两边同乘最简公分母）化为整式方程 → 解整式方程 → 把结果代入最简公分母检验。","必须检验：若代入最简公分母后为 0，则这个根是增根，必须舍去，此时原方程无解。「有增根」的含义是增根恰为使最简公分母为 0 的那个 x 值，常用于求参数。「无解」与「有增根」不是同一件事，但都由检验得出。"],["不等式的性质 1","不等式两边加（或减）同一个数（或整式），不等号的方向不变。","加减运算不改变不等号方向，可以放心使用；这一条也是解不等式「移项」的依据（移项变号、不等号方向不变）。"],["不等式的性质 2","不等式两边乘（或除以）同一个正数，不等号的方向不变。","必须先确认乘数（除数）是正数才能用；系数是字母时要讨论它的符号，不能直接两边同除。"],["不等式的性质 3 ★","不等式两边乘（或除以）同一个负数，不等号的方向改变。","「变号」是解不等式最常见的错误来源：-2x>6 两边同除以 -2 得 x<-3（不是 x>-3）。若乘数的符号未知，不能两边同乘，必须分类讨论。"],["解一元一次不等式的步骤","去分母 → 去括号 → 移项 → 合并同类项 → 系数化为 1（如果两边同除以负数，不等号方向要改变）。","步骤与解一元一次方程完全相同，唯一的区别在最后一步：系数为负数时不等号方向改变。解集在数轴上表示时，含等号（≥、≤）画实心圆点，不含等号（>、<）画空心圆点，方向按「大于向右、小于向左」。"],["一元一次不等式组的解集（四种情况）★","设 a>b：①casesx>ax>bendcases 的解集是 x>a（同大取大）；②casesx<ax<bendcases 的解集是 x<b（同小取小）；③casesx>ax<bendcases 无解（大大小小无解）；④casesx<bx>aendcases 的解集是 a<x<b（大小小大中间找）。","口诀「同大取大、同小取小、大大小小无解、大小小大中间找」的前提是两个不等式的解集边界 a、b 已确定大小关系。含等号时要特别注意端点能否取到（如 x≥ a 与 x<b 无解当且仅当 a≥ b）。判断时画数轴最稳。"]]},{"type":"note","title":"例题","text":"解方程 x²-6x+5=0，并说明为什么可以用两种方法。"},{"type":"figure","figure":{"id":"fig-for-fangcheng-e1","title":"抛物线 y=(x−1)(x−5) 与 x 轴的交点","caption":"两根 1、5 就是抛物线与 x 轴交点的横坐标，顶点为 (3,−4)","view":"square","alt":"平面直角坐标系中一条开口向上的抛物线，与 x 轴交于点 (1,0) 和 (5,0)，顶点坐标为 (3,−4)，对称轴为直线 x=3，与 y 轴交于 (0,5)","prims":[{"t":"plane","x":25,"y":60,"right":60,"left":25,"up":50,"down":35,"xLabel":"x","yLabel":"y","xTicks":[{"at":10,"label":"1"},{"at":30,"label":"3"},{"at":50,"label":"5"}],"yTicks":[{"at":30,"label":"5"},{"at":-24,"label":"−4"}]},{"t":"line","x1":55,"y1":20,"x2":55,"y2":92,"dashed":true,"tone":"muted"},{"t":"text","x":55,"y":16,"text":"x=3","size":3.2,"tone":"muted"},{"t":"curve","points":[[25,30],[30,45],[35,60],[40,71],[45,78],[50,82],[55,84],[60,82],[65,78],[70,71],[75,60],[80,45],[85,30]],"tone":"accent","width":2},{"t":"dot","x":35,"y":60,"r":1.4,"label":"(1,0)","labelDx":-3,"labelDy":5},{"t":"dot","x":75,"y":60,"r":1.4,"label":"(5,0)","labelDx":2,"labelDy":5},{"t":"dot","x":55,"y":84,"r":1.4,"tone":"accent","label":"(3,−4)","labelDx":3,"labelDy":4},{"t":"dot","x":25,"y":30,"r":1.4,"tone":"muted","label":"(0,5)","labelDx":2,"labelDy":4}]}},{"type":"list","title":"解题步骤","items":["方法一（因式分解法）：把左边分解为 (x-1)(x-5)=0，由「两个因式的积为 0」得 x-1=0 或 x-5=0，所以 x₁=1，x₂=5。","方法二（公式法）：a=1，b=-6，c=5，先算 Δ=(-6)²-4×1×5=16>0，说明有两个不相等的实数根。","代入求根公式：x=6±√(16)2=(6±4)/(2)，得 x₁=1，x₂=5。","检验两根：x₁+x₂=6=-(b)/(a)，x₁x₂=5=(c)/(a)，与韦达定理一致，结果正确。"]},{"type":"p","text":"答案：x₁=1，x₂=5"},{"type":"note","title":"方法小结","text":"这张卡的用法是「先选方法、再查结论」：能因式分解就优先因式分解（快且不容易算错），先算 Δ 可以提前判断根的个数，避免在 Δ<0 时硬套公式。含参数题则先想判别式与韦达定理。"},{"type":"note","title":"例题","text":"某商店 1 月份的利润为 20 万元，由于经营改善，3 月份的利润增加到 24.2 万元。求该商店利润的月平均增长率。"},{"type":"figure","figure":{"id":"fig-for-fangcheng-e2","title":"连续两期增长：20(1+x)²=24.2","caption":"1 月到 3 月经过 2 个月，每月都是乘 (1+x)","view":"wide","alt":"三个逐渐升高的柱子，分别标着 1 月的 20 万元、2 月的 20 乘 (1 加 x)、3 月的 24.2 万元，柱子之间有箭头表示每个月都乘一次 (1 加 x)","prims":[{"t":"line","x1":8,"y1":56,"x2":92,"y2":56,"tone":"muted"},{"t":"rect","x":16,"y":38,"w":14,"h":18,"tone":"main","fill":true},{"t":"rect","x":42,"y":30,"w":14,"h":26,"tone":"accent","fill":true},{"t":"rect","x":68,"y":22,"w":14,"h":34,"tone":"ok","fill":true},{"t":"text","x":23,"y":34,"text":"20","size":3.6},{"t":"text","x":49,"y":26,"text":"20(1+x)","size":3.4},{"t":"text","x":75,"y":18,"text":"24.2","size":3.6},{"t":"text","x":23,"y":61,"text":"1 月","size":3.4,"tone":"muted"},{"t":"text","x":49,"y":61,"text":"2 月","size":3.4,"tone":"muted"},{"t":"text","x":75,"y":61,"text":"3 月","size":3.4,"tone":"muted"},{"t":"arrow","x1":30.5,"y1":50,"x2":41.5,"y2":50},{"t":"arrow","x1":56.5,"y1":50,"x2":67.5,"y2":50},{"t":"text","x":50,"y":8,"text":"每个月都乘一次 (1+x)","size":3.4,"tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["设月平均增长率为 x，从 1 月到 3 月经过了 2 个月。","按平均增长率模型列方程：20(1+x)²=24.2。","两边同除以 20，得 (1+x)²=1.21，开平方得 1+x=± 1.1。","解得 x₁=0.1，x₂=-2.1；增长率不能为负，舍去 x₂，所以月平均增长率为 10\\%。"]},{"type":"p","text":"答案：该商店利润的月平均增长率为 10\\%。"},{"type":"note","title":"方法小结","text":"连续两期增长用 a(1+x)²=b，不要只增长一次；开平方得到正负两个值后，必须按实际意义舍去负数根。"},{"type":"note","title":"例题","text":"解不等式组 cases(x+1)/(2)≥ 1 \\\\ 3x-2<x+4endcases，并把解集在数轴上表示出来。"},{"type":"figure","figure":{"id":"fig-m-for-fangcheng-1","title":"在数轴上表示解集 1≤x<3","caption":"1 处画实心圆点、3 处画空心圆点，两点之间加粗的部分就是公共解集","view":"wide","alt":"一条水平数轴，刻度 1 的位置画实心圆点，刻度 3 的位置画空心圆点，1 与 3 之间的部分加粗，表示不等式组的解集为 1 小于等于 x 小于 3","prims":[{"t":"arrow","x1":12,"y1":50,"x2":88,"y2":50},{"t":"line","x1":35,"y1":47,"x2":35,"y2":53,"tone":"muted"},{"t":"line","x1":65,"y1":47,"x2":65,"y2":53,"tone":"muted"},{"t":"line","x1":35,"y1":50,"x2":65,"y2":50,"tone":"accent","width":2.5},{"t":"dot","x":35,"y":50,"r":1.5,"tone":"accent"},{"t":"dot","x":65,"y":50,"r":1.5,"hollow":true,"tone":"accent"},{"t":"text","x":35,"y":60,"text":"1","size":3.6,"anchor":"middle"},{"t":"text","x":65,"y":60,"text":"3","size":3.6,"anchor":"middle"},{"t":"text","x":50,"y":36,"text":"1 ≤ x < 3","size":3.8,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["解第一个不等式：(x+1)/(2)≥ 1，两边同乘 2 得 x+1≥ 2，解得 x≥ 1。","解第二个不等式：3x-2<x+4，移项合并得 2x<6，解得 x<3。","画数轴取两个解集的公共部分：x≥ 1 处画实心圆点向右，x<3 处画空心圆点向左。","两部分重叠的区间为 1≤ x<3，这就是不等式组的解集。"]},{"type":"p","text":"答案：不等式组的解集为 1≤ x<3；数轴上 1 处画实心圆点、3 处画空心圆点，取两者之间的部分。"},{"type":"note","title":"方法小结","text":"不等式组的解集是各不等式解集的公共部分；含等号画实心圆点、不含等号画空心圆点，端点取舍不能凭感觉，要逐个代回原不等式检验。"},{"type":"list","title":"易错点","items":["不等式两边同乘（除以）负数时忘记改变不等号方向；当乘数是含字母的式子时，不讨论符号就直接乘，也是错的。","用韦达定理前不检验 $\\Delta\\geq0$，对没有实数根的方程照样算出「两根之和」。","解分式方程不检验增根，或把「有增根」与「原方程无解」混为一谈。","解一元二次方程时两边同时约去含未知数的因式（如由 $x^2=3x$ 得 $x=3$），丢掉 $x=0$ 这个根。"]},{"type":"list","title":"解题方法","items":["解一元二次方程按「一分二公」选法：先看能否直接开平方，再看能否因式分解，都不行才用公式法；动手前先算 Δ，可直接得到根的个数结论。","不等式组的解集用数轴判断：把每个不等式的解集画在同一条数轴上，公共部分就是解集，比死记「同大取大」更不容易出错。","解分式方程记「一乘、二解、三检验」，检验必须写在解答过程中；求含参数的分式方程「有增根」问题时，先把增根（使最简公分母为 0 的值）找出来，再代回整式方程求参数。"]}],"questions":[{"id":"q-m-for-fangcheng-1","type":"choice","stem":"一元二次方程 x²-4x+1=0 的根的情况是","answer":"A","explain":"a=1，b=-4，c=1，Δ=b²-4ac=(-4)²-4×1×1=12>0，所以方程有两个不相等的实数根。","options":["有两个不相等的实数根","有两个相等的实数根","没有实数根","无法确定"],"difficulty":1,"tags":["判别式"]},{"id":"q-m-for-fangcheng-2","type":"fill","stem":"若 x₁、x₂ 是方程 x²-5x+3=0 的两个实数根，则 x₁²+x₂² 的值是____。","answer":"19","explain":"先检验 Δ=25-12=13>0，两根存在。由韦达定理 x₁+x₂=5，x₁x₂=3，所以 x₁²+x₂²=(x₁+x₂)²-2x₁x₂=25-6=19。","difficulty":2,"tags":["韦达定理","公式变形"]},{"id":"q-m-for-fangcheng-3","type":"choice","stem":"若 a>b，则下列不等式一定成立的是","answer":"B","explain":"不等式两边同时减去 3，不等号方向不变，故 B 一定成立。A、D 中 c 的符号未知（c<0 时不等号要变向，c=0 时不成立）；C 两边同乘 -2，不等号应变向，正确结果应为 -2a<-2b。","options":["ac>bc","a-3>b-3","-2a>-2b","(a)/(c)>(b)/(c)"],"difficulty":2,"tags":["不等式性质","不等号变号"]},{"id":"q-m-for-fangcheng-4","type":"short","stem":"解分式方程 (2)/(x-1)=(3)/(x)，并说明为什么必须检验。","answer":"两边同乘最简公分母 $x(x-1)$，得 $2x=3(x-1)$，即 $2x=3x-3$，解得 $x=3$。检验：当 $x=3$ 时，$x(x-1)=3\\times2=6\\neq0$，所以 $x=3$ 是原方程的根。","explain":"去分母时两边同乘的是含未知数的整式 x(x-1)，这个式子在 x=0 或 x=1 时等于 0。当 x=0 或 x=1 时，同乘的过程相当于两边乘了 0，会使本不成立的等式变成立，从而产生增根，所以必须把求得的根代入最简公分母检验：不为 0 才是原方程的根，为 0 则舍去。","difficulty":2,"tags":["分式方程","增根检验"],"rubric":["确定最简公分母 x(x-1)，两边同乘化为整式方程 2x=3(x-1)","正确解出整式方程得 x=3","写出检验过程：代入最简公分母，x(x-1)=6≠0","给出结论 x=3 是原方程的根，并说明增根产生的原因（两边同乘了可能为 0 的整式）"]},{"id":"q-m-for-fangcheng-z1","type":"choice","stem":"若关于 x 的一元二次方程 x²-2x+k=0 有两个不相等的实数根，则 k 的取值范围是","answer":"A","explain":"方程有两个不相等的实数根等价于判别式 Δ>0。这里 a=1，b=-2，c=k，故 Δ=(-2)²-4× 1× k=4-4k>0，解得 k<1。取等号时 Δ=0，方程只有两个相等的实数根，故 B 不正确。","options":["k<1","k≤ 1","k>1","k≠ 1"],"difficulty":2,"tags":["判别式","含参数"]},{"id":"q-m-for-fangcheng-z2","type":"fill","stem":"不等式 3-2x≥ 7 的解集是____。","answer":"x\\leq -2|x≤-2","explain":"移项得 -2x≥ 7-3，即 -2x≥ 4；两边同除以 -2，不等号方向改变，得 x≤ -2。最容易出错的一步就是除以负数时忘记把「≥」改成「≤」。","difficulty":2,"tags":["一元一次不等式","不等号变号"]}]},{"id":"m-for-hanshu","title":"函数图像与性质速查","subtitle":"速查 · 函数","grade":"all","tags":["公式与定理","函数"],"blocks":[{"type":"note","title":"教材章节","text":"速查 · 函数"},{"type":"note","title":"一句话概述","text":"正比例函数、一次函数、反比例函数、二次函数的解析式、图像位置与性质集中速查，重点是系数符号与图像、最值与对称轴。"},{"type":"h","text":"核心概念"},{"type":"p","text":"本卡怎么用：四种函数的解析式与图像性质集中在一张卡上，按「正比例函数 → 一次函数 → 反比例函数 → 二次函数」排列，每种函数都按「解析式 → 图像 → 增减性 → 求解析式的方法」四步走。"},{"type":"p","text":"三步定位法：第一步看是哪种函数（x 的次数与位置：一次、反比例还是二次）；第二步看系数符号（k、b、a）；第三步看图像特征（过哪几个象限、顶点、对称轴、最值）。任何一道函数题都可以按这三步拆开。"},{"type":"p","text":"带 ★ 的是必考：带 ★ 的条目是高频点：一次函数中 k、b 与图像位置、反比例函数中 k 的几何意义、二次函数的顶点坐标公式与对称轴、二次函数的最值（含自变量取值范围的限制）。"},{"type":"p","text":"先画草图再计算：函数题的第一动作是画草图：单调性、交点个数、最值取在哪一点，看草图比空算代数式快得多。比较函数值大小、解 kx+b>0 这类不等式，一律转化为「图像在 x 轴上方（下方）的部分对应的 x 的取值范围」。"},{"type":"note","title":"中考考法","text":"待定系数法求函数解析式\n一次函数代两点列方程组，二次函数按交点式、顶点式、一般式的已知条件选形式设式，是函数综合题第一问的固定考法。"},{"type":"note","title":"中考考法","text":"二次函数的图像特征与最值\n由 a 判开口、由顶点式或坐标公式得顶点与对称轴，实际问题最值必须检验顶点横坐标是否在自变量取值范围内。"},{"type":"note","title":"中考考法","text":"反比例函数 k 的几何意义\n矩形面积等于 |k|、对应三角形面积等于其半，由面积反求 k 要结合象限定符号，增减性必须表述为「在每一支上」。"},{"type":"note","title":"中考考法","text":"函数与方程、不等式的转化\n图像与 x 轴交点的横坐标就是对应方程的根，kx+b>0 转化为图像在轴上方部分的横坐标范围，用数形结合求解。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["正比例函数","y 与 x 成正比例，图像是一条经过原点的直线。","图像必过原点 (0,0)。k>0 时图像在第一、三象限，y 随 x 的增大而增大；k<0 时在第二、四象限，y 随 x 的增大而减小。它是 y=kx+b 中 b=0 的特殊情形，只需一个已知点就能求解析式。"],["一次函数","形如 y=kx+b（k、b 为常数，k≠0）的函数叫一次函数，图像是一条直线。","b 是直线与 y 轴交点的纵坐标，即与 y 轴交于 (0,b)。k≠0 是定义的一部分，k=0 时 y=b 是常函数不是一次函数。直线与 x 轴交于 (-(b)/(k),0)。"],["一次函数的增减性","k>0 时，y 随 x 的增大而增大，图像从左到右上升；k<0 时，y 随 x 的增大而减小，图像从左到右下降。","增减性只由 k 决定，与 b 无关。比较两个点对应的函数值大小时，先判断两点是否在同一「侧」并不重要——一次函数在整个实数范围内单调，直接由 k 的符号即可判断。"],["一次函数图像经过的象限（k、b 的符号）★","k>0,b>0 时经过第一、二、三象限；k>0,b<0 时经过第一、三、四象限；k<0,b>0 时经过第一、二、四象限；k<0,b<0 时经过第二、三、四象限。","口诀：k 定方向（k>0 上升、k<0 下降），b 定截距（b>0 与 y 轴交于正半轴、b<0 交于负半轴、b=0 过原点）。注意四条情形都「经过第一、三象限」或「经过第二、四象限」的部分由 k 决定，b 只影响另一侧的象限。"],["待定系数法求函数解析式","设出含待定字母的解析式，把图像上已知点的坐标代入，得到方程（组），解出待定字母。","两点确定一条直线，所以求一次函数解析式需要两个已知点（设 y=kx+b 得二元一次方程组）；正比例函数只需一个点（设 y=kx）。求出后要把解析式写完整并注明 k≠0，代入第三个点可以自检。"],["一次函数与方程、不等式的关系","直线 y=kx+b 与 x 轴交点的横坐标，就是方程 kx+b=0 的解；kx+b>0 的解集就是图像位于 x 轴上方部分对应的 x 的取值范围。","两条直线 y=k₁x+b₁ 与 y=k₂x+b₂ 的交点坐标就是对应二元一次方程组的解；当 k₁=k₂ 且 b₁≠ b₂ 时两直线平行，对应的方程组无解；当 k₁=k₂ 且 b₁=b₂ 时两直线重合，方程组有无数组解。"],["反比例函数","形如 y=(k)/(x)（k 为常数，k≠0）的函数叫反比例函数，图像是双曲线。","自变量 x≠0，函数值 y≠0，图像与两坐标轴永不相交；图像关于原点成中心对称，也关于直线 y=x、y=-x 成轴对称。也可写成 xy=k 或 y=kx^(-1)（后者说明 x 的指数为 -1）。"],["反比例函数的图像与性质 ★","k>0 时，图像在第一、三象限，在每一支上 y 随 x 的增大而减小；k<0 时，图像在第二、四象限，在每一支上 y 随 x 的增大而增大。","必须强调「在每一支上」：k>0 时不能说「y 随 x 增大而减小」，因为跨越两支时不成立（如 y=(6)/(x)，x=-1 时 y=-6，x=1 时 y=6）。比较两点函数值大小时，若两点不在同一支上，需分别算出函数值或用图像判断。"],["反比例函数中 k 的几何意义 ★","过双曲线上任意一点 P 向两坐标轴作垂线，与坐标轴围成的矩形面积 S₁=|k|；连接 P 与原点及一条垂足所得的直角三角形面积 S₂=(1)/(2)|k|。","面积带绝对值，所以 k<0 时面积仍为正数；由面积反求 k 时，必须结合图像所在象限确定 k 的符号（面积只给出 |k|，会有两个答案）。"],["二次函数的一般式","形如 y=ax²+bx+c（a、b、c 为常数，a≠0）的函数叫二次函数。","a≠0 是定义的一部分。图像与 y 轴必有一个交点 (0,c)，所以 c 就是纵截距。已知图像上任意三个点（且不都在同一水平线上）时用一般式配合待定系数法求解。"],["二次函数的顶点式","顶点式能直接读出抛物线的顶点坐标和对称轴。","顶点坐标是 (h,k)，对称轴是直线 x=h。括号里是 -h，所以 y=2(x-3)²+1 的顶点是 (3,1) 而不是 (-3,1)，这是最高频的读错点。已知顶点（或最值）与另一点时用它最方便。"],["二次函数的交点式","当抛物线与 x 轴交于 (x₁,0)、(x₂,0) 时，可设成交点式。","因为要与 x 轴有两个交点，所以必须满足 Δ=b²-4ac≥0（Δ=0 时两交点重合，交点式退化为顶点式的特殊情形）。已知与 x 轴的两个交点及另一点时用它最省事，比设一般式列三元方程组快得多。"],["顶点坐标公式与对称轴 ★","把一般式配方即得顶点坐标公式与对称轴方程。","顶点纵坐标 (4ac-b²)/(4a) 与 Δ=b²-4ac 只差一个负号，可记为 -(Δ)/(4a)，别把符号记反。对称轴 x=-(b)/(2a) 也可理解为两交点横坐标的中点 (x₁+x₂)/(2)。"],["二次函数图像的开口方向与最值 ★","a>0 时开口向上，顶点是最低点，函数有最小值 (4ac-b²)/(4a)；a<0 时开口向下，顶点是最高点，函数有最大值 (4ac-b²)/(4a)。|a| 越大，开口越小。","开口方向只由 a 的符号决定；最值等于顶点纵坐标。特别提醒：求最值必须先看自变量的取值范围——若对称轴落在给定区间内，最值在顶点取到；若不在区间内，最值在区间端点取到（这是实际问题最常见的失分点）。"],["二次函数图像与 x 轴的交点个数","Δ=b²-4ac>0 时图像与 x 轴有两个交点；Δ=0 时只有一个交点（顶点在 x 轴上）；Δ<0 时没有交点。","交点个数与方程 ax²+bx+c=0 的实数根个数一一对应，是数形结合的核心结论，判定时要把「图像交点」翻译成「方程的根」再算 Δ。另外，图像与 y 轴必有一个交点 (0,c)，与 x 轴可能没有交点。"],["二次函数图像的平移规律","把 y=ax² 的图像向左（右）平移 h 个单位、向上（下）平移 k 个单位，就得到 y=a(x-h)²+k：左右平移遵循「左加右减」（作用在 x 上），上下平移遵循「上加下减」（作用在整体上）。","平移只改变位置不改变形状，所以 a 不变。「左加右减」是在括号内对 x 加减，如向右平移 2 个单位写成 y=a(x-2)²+k，写反方向是高频错误；若给出的是顶点式，直接看顶点如何移动即可。"],["抛物线的对称性","抛物线上纵坐标相等的两个点关于对称轴对称，对称轴是这两个点横坐标的中点所在的直线。","由对称轴是两交点横坐标的中点可得 x₁+x₂=-(b)/(a)，与韦达定理一致。已知抛物线上两点 (x₁,y)、(x₂,y)（纵坐标相同）时，可用 x=(x₁+x₂)/(2) 快速求对称轴；反之，已知对称轴可求与已知点对称的另一个点。"],["用二次函数求实际问题的最值","设出自变量并写清取值范围 → 根据等量关系列出二次函数解析式 → 配方成顶点式（或用顶点坐标公式）求最值 → 检验最值点是否在取值范围内。","实际问题中自变量通常有范围限制（边长必须为正、件数为整数等）。若顶点横坐标不在取值范围内，就要比较区间端点处的函数值来确定最值，不能想当然地取顶点。"]]},{"type":"note","title":"例题","text":"已知抛物线经过点 (1,0)、(3,0) 和 (0,3)，求它的解析式与顶点坐标。"},{"type":"figure","figure":{"id":"fig-m-for-hanshu-1","title":"抛物线 y=(x−1)(x−3) 的图像","caption":"抛物线与 x 轴交于 (1,0)、(3,0)，与 y 轴交于 (0,3)，顶点为 (2,−1)","view":"wide","alt":"平面直角坐标系中，一条开口向上的抛物线与 x 轴交于点 (1,0) 和 (3,0)，与 y 轴交于点 (0,3)，顶点坐标为 (2,−1)，对称轴为直线 x=2","prims":[{"t":"axis","x":20,"y":60,"w":70,"h":50,"xLabel":"x","yLabel":"y","origin":true,"xTicks":[{"at":0.14,"label":"1"},{"at":0.43,"label":"3"}],"yTicks":[{"at":0.6,"label":"3"}]},{"t":"curve","points":[[20,30],[25,42.5],[30,60],[35,67.5],[40,70],[45,67.5],[50,60],[55,42.5],[60,30]],"tone":"accent","width":2},{"t":"line","x1":40,"y1":8,"x2":40,"y2":72,"dashed":true,"tone":"muted"},{"t":"dot","x":30,"y":60,"r":1.4,"label":"(1,0)","labelDx":-3,"labelDy":4},{"t":"dot","x":50,"y":60,"r":1.4,"label":"(3,0)","labelDx":2,"labelDy":4},{"t":"dot","x":20,"y":30,"r":1.4,"label":"(0,3)","labelDx":-14,"labelDy":0},{"t":"dot","x":40,"y":70,"r":1.4,"tone":"accent","label":"(2,−1)","labelDx":3,"labelDy":4},{"t":"text","x":40,"y":5,"text":"x=2","size":3.2,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["先看清已知条件：抛物线与 x 轴的两个交点分别为 (1,0)、(3,0)，所以设交点式 y=a(x-1)(x-3)。","把第三个点 (0,3) 代入：3=a(0-1)(0-3)=3a，解得 a=1。","展开得解析式 y=(x-1)(x-3)=x²-4x+3。","求顶点：对称轴 x=-(b)/(2a)=(1+3)/(2)=2，代入得 y=4-8+3=-1，所以顶点坐标为 (2,-1)。"]},{"type":"p","text":"答案：y=x²-4x+3，顶点坐标为 (2,-1)"},{"type":"note","title":"方法小结","text":"这张卡最重要的用法是「按已知条件选形式」：已知与 x 轴的两个交点用交点式，已知顶点用顶点式，只有已知任意三点才用一般式。选对形式可以少列两个方程；求顶点时也可以直接用对称轴是两交点中点的性质。"},{"type":"note","title":"例题","text":"已知一次函数的图像经过点 (1,3) 和点 (-1,-1)。求这个一次函数的解析式，并判断点 (2,5) 是否在该函数的图像上。"},{"type":"list","title":"解题步骤","items":["设一次函数的解析式为 y=kx+b（k≠ 0）。","把两个已知点的坐标分别代入，得方程组 casesk+b=3 \\\\ -k+b=-1endcases，两式相加得 2b=2，所以 b=1，再代回得 k=2。","所以这个一次函数的解析式为 y=2x+1。","检验点 (2,5)：把 x=2 代入解析式得 y=2× 2+1=5，与该点纵坐标相等，所以点 (2,5) 在该函数的图像上。"]},{"type":"p","text":"答案：一次函数的解析式为 y=2x+1；点 (2,5) 在该函数的图像上。"},{"type":"note","title":"方法小结","text":"两点确定一条直线，代两点求 k、b 是待定系数法的标准流程；判断一个点是否在图像上，只需把横坐标代入解析式，看算出的纵坐标是否与点的纵坐标相等。"},{"type":"note","title":"例题","text":"已知反比例函数 y=(k)/(x) 的图像经过点 A(2,3)。求 k 的值，并求过点 A 向两坐标轴所作垂线与坐标轴围成的矩形面积，以及连接点 A 与原点把该矩形分成的每个直角三角形的面积。"},{"type":"figure","figure":{"id":"fig-for-fanbili-e1","title":"图象经过的点代入求解析式","caption":"反比例函数 y = k/x 的图象经过点 A(2,3)：把 A 的坐标代入，由 xy = k 得 k = 2×3 = 6，解析式为 y = 6/x","view":"square","alt":"平面直角坐标系中第一象限的一段反比例函数图象，图象上标出点 A 并注明坐标 A(2,3)，从 A 向两条坐标轴画有虚线。","prims":[{"t":"arrow","x1":16,"y1":69.2,"x2":88,"y2":69.2,"tone":"muted"},{"t":"arrow","x1":23,"y1":78,"x2":23,"y2":12,"tone":"muted"},{"t":"text","x":89,"y":71.2,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":25.4,"y":11,"text":"y","size":3.4,"tone":"muted"},{"t":"text","x":18.4,"y":72.4,"text":"O","size":3.2,"tone":"muted"},{"t":"curve","points":[[39.2,22.1],[40.4,25.2],[41.5,28],[42.7,30.4],[43.9,32.5],[45,34.5],[46.2,36.2],[47.4,37.8],[48.5,39.2],[49.7,40.5],[50.8,41.7],[52,42.8],[53.2,43.8],[54.3,44.8],[55.5,45.6],[56.6,46.4],[57.8,47.2],[59,47.9],[60.1,48.6],[61.3,49.2],[62.5,49.8],[63.6,50.3],[64.8,50.9],[65.9,51.4],[67.1,51.8],[68.3,52.3],[69.4,52.7],[70.6,53.1],[71.7,53.5],[72.9,53.9],[74.1,54.2],[75.2,54.5],[76.4,54.9],[77.5,55.2],[78.7,55.4],[79.9,55.7],[81,56],[82.2,56.3],[83.4,56.5],[84.5,56.7],[85.7,57],[86.8,57.2],[88,57.4]],"tone":"accent"},{"t":"poly","points":[[23,69.2],[46.2,69.2],[46.2,36.2],[23,36.2]],"closed":true,"tone":"ok","fill":true},{"t":"line","x1":46.2,"y1":36.2,"x2":46.2,"y2":69.2,"tone":"muted","dashed":true},{"t":"line","x1":46.2,"y1":36.2,"x2":23,"y2":36.2,"tone":"muted","dashed":true},{"t":"circle","cx":46.2,"cy":36.2,"r":1.6,"tone":"danger","fill":true},{"t":"text","x":49.2,"y":34.8,"text":"A(2, 3)","anchor":"start","size":3.6,"tone":"danger"},{"t":"text","x":20,"y":16,"text":"y = k/x","anchor":"start","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":74,"text":"k = x · y = 2 × 3 = 6","anchor":"middle","size":3.6,"tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["把点 A(2,3) 代入 y=(k)/(x)，得 3=(k)/(2)，所以 k=2× 3=6。","过双曲线上一点向两坐标轴作垂线，围成矩形的面积等于 |k|，所以矩形面积为 |6|=6。","也可直接验证：矩形的长和宽分别为 2 和 3，面积为 2× 3=6。","连接点 A 与原点，把矩形分成两个全等的直角三角形，每个三角形的面积为矩形面积的一半，即 (1)/(2)× 6=3。"]},{"type":"p","text":"答案：k=6；矩形面积为 6；每个直角三角形的面积为 3。"},{"type":"note","title":"方法小结","text":"反比例函数中 k 的几何意义是面积结论：矩形面积为 |k|，直角三角形面积为 (1)/(2)|k|。面积不带符号，已知面积反求 k 时还要结合图像所在象限确定正负。"},{"type":"list","title":"易错点","items":["反比例函数的增减性漏掉「在每一支上」，跨越两支比较函数值时会得出错误结论。","顶点式 $y=a(x-h)^2+k$ 的顶点误读成 $(-h,k)$；顶点纵坐标 $\\frac{4ac-b^2}{4a}$ 与 $\\Delta=b^2-4ac$ 的符号记混。","求二次函数最值时忽略自变量的取值范围，顶点取不到时仍然直接写顶点纵坐标。","一次函数中 $k$、$b$ 与图像经过的象限对应关系记错，特别是 $k>0,b<0$ 与 $k<0,b>0$ 两种情形。"]},{"type":"list","title":"解题方法","items":["数形结合：一次函数看 k 定方向、b 定截距；反比例函数看 k 定象限、看 |k| 定面积；二次函数看 a 定开口、看对称轴定位置、看顶点定最值。动手算之前先画草图是最高效的习惯。","待定系数法的设式口诀：两点（或正比例）设 y=kx+b；已知顶点设 y=a(x-h)²+k；已知与 x 轴两交点设 y=a(x-x₁)(x-x₂)；其余情况设一般式。","比较函数值大小、解 kx+b>0、判断 ax²+bx+c>0 的解集，都转化为「图像在 x 轴上方（或下方）的部分」，把代数问题交给图像判断。"]}],"questions":[{"id":"q-m-for-hanshu-1","type":"choice","stem":"一次函数 y=-2x+3 的图像不经过","answer":"C","explain":"k=-2<0，图像从左到右下降；b=3>0，图像与 y 轴交于正半轴。故图像经过第一、二、四象限，不经过第三象限。","options":["第一象限","第二象限","第三象限","第四象限"],"difficulty":2,"tags":["一次函数","图像与象限"]},{"id":"q-m-for-hanshu-2","type":"fill","stem":"二次函数 y=x²-4x+5 的顶点坐标是____。","answer":"(2,1)","explain":"方法一：x=-(b)/(2a)=-(-4)/(2)=2，代入得 y=4-8+5=1，顶点为 (2,1)。方法二：配方 y=(x-2)²+1，顶点为 (2,1)。","difficulty":1,"tags":["二次函数","顶点坐标"]},{"id":"q-m-for-hanshu-3","type":"choice","stem":"若点 A(-2,y₁)、B(-1,y₂) 都在反比例函数 y=(6)/(x) 的图像上，则","answer":"A","explain":"k=6>0，图像在第一、三象限，在每一支上 y 随 x 的增大而减小。A、B 两点的横坐标都是负数，在同一支（第三象限）上，且 -2<-1，所以 y₁>y₂。直接计算也验证：y₁=-3，y₂=-6，y₁>y₂。","options":["y₁>y₂","y₁<y₂","y₁=y₂","无法确定大小关系"],"difficulty":2,"tags":["反比例函数","增减性"]},{"id":"q-m-for-hanshu-4","type":"short","stem":"指出抛物线 y=2x²-4x+1 的开口方向、对称轴和顶点坐标，并求它的最小值。","answer":"因为 $a=2>0$，开口向上；对称轴为直线 $x=-\\frac{b}{2a}=1$；配方得 $y=2(x-1)^2-1$，顶点坐标为 $(1,-1)$；开口向上时顶点是最低点，所以最小值为 $-1$。","explain":"a=2>0 决定开口向上；对称轴用 x=-(b)/(2a)=(4)/(4)=1；配方：y=2(x²-2x)+1=2(x-1)²-2+1=2(x-1)²-1，故顶点 (1,-1)。开口向上时函数在顶点处取最小值 -1（本题自变量取全体实数，顶点在范围内）。","difficulty":2,"tags":["二次函数","顶点与最值"],"rubric":["由 a=2>0 得出开口向上","正确求出对称轴 x=-(b)/(2a)=1","用配方或顶点坐标公式得出顶点 (1,-1)","说明开口向上时顶点处取最小值，最值为 -1"]},{"id":"q-m-for-hanshu-z1","type":"choice","stem":"关于二次函数 y=(x-1)²+2 的图像，下列说法正确的是","answer":"D","explain":"顶点式 y=a(x-h)²+k 中 a=1>0，开口向上，A 错；顶点为 (h,k)=(1,2)，不是 (-1,2)，B 错；对称轴为直线 x=1，C 错；开口向上时顶点 (1,2) 是最低点，故 x=1 时 y 取最小值 2，D 正确。","options":["开口向下","顶点坐标为 (-1,2)","对称轴是直线 x=-1","当 x=1 时，y 取得最小值 2"],"difficulty":2,"tags":["二次函数","顶点式"]},{"id":"q-m-for-hanshu-z2","type":"short","stem":"如图，用长 24 m 的篱笆靠墙围成一个矩形花圃（墙足够长），设垂直于墙的一边长为 x m，花圃面积为 S m²。求 S 与 x 的函数关系式，并求花圃的最大面积及此时平行于墙的一边长。","answer":"垂直于墙的一边长为 $x$ m，则平行于墙的一边长为 $(24-2x)$ m，由题意 $x>0$ 且 $24-2x>0$，即 $0<x<12$。面积 $S=x(24-2x)=-2x^2+24x=-2(x-6)^2+72$。因为 $-2<0$ 且 $6$ 在 $0<x<12$ 内，所以当 $x=6$ 时 $S$ 取得最大值 72；此时平行于墙的一边长为 $24-2\\times 6=12$（m）。","explain":"靠墙围矩形时篱笆只围三边，两条垂直于墙的边各长 x，平行于墙的边长为 24-2x。面积整理成顶点式后，顶点横坐标 6 在取值范围 0<x<12 内，最值才能在顶点取到；若顶点超出范围，就应比较区间端点的面积。","difficulty":3,"tags":["二次函数","实际问题最值"],"rubric":["写出平行于墙的边长 24-2x 及面积关系式 S=x(24-2x)","配方为 S=-2(x-6)²+72，并确定自变量范围 0<x<12","由顶点在取值范围内得最大面积 72 m²，并求出平行于墙的边长为 12 m"],"figure":{"id":"fig-m-for-hanshu-z2","title":"靠墙围成的矩形花圃","caption":"篱笆只围三边：两条垂直于墙的边长各为 x，平行于墙的边长为 24−2x","view":"wide","alt":"上方是一道带斜线阴影的墙，下方靠墙围出一个矩形花圃，矩形的左右两条边各标为 x，底边标为 24 减 2x，顶边与墙重合","prims":[{"t":"hatch","x":15,"y":14,"w":70,"h":6},{"t":"line","x1":15,"y1":20,"x2":85,"y2":20,"tone":"muted"},{"t":"line","x1":32,"y1":20,"x2":32,"y2":58,"width":2},{"t":"line","x1":32,"y1":58,"x2":68,"y2":58,"width":2},{"t":"line","x1":68,"y1":20,"x2":68,"y2":58,"width":2},{"t":"text","x":50,"y":16,"text":"墙","size":3.6,"anchor":"middle","tone":"muted"},{"t":"text","x":28,"y":40,"text":"x","size":3.8,"anchor":"end"},{"t":"text","x":72,"y":40,"text":"x","size":3.8,"anchor":"start"},{"t":"text","x":50,"y":64,"text":"24−2x","size":3.6,"anchor":"middle"}]}}]},{"id":"m-for-jihe","title":"几何定理速查","subtitle":"速查 · 图形与几何","grade":"all","tags":["公式与定理","图形与几何"],"blocks":[{"type":"note","title":"教材章节","text":"速查 · 图形与几何"},{"type":"note","title":"一句话概述","text":"线段、角、相交线与平行线的基本定理，以及平面直角坐标系中的对称与平移规律速查，是后面三角形与四边形证明的地基。"},{"type":"h","text":"核心概念"},{"type":"p","text":"本卡怎么用：按「线段与角 → 相交线（对顶角、垂线）→ 平行线 → 平移 → 平面直角坐标系」的顺序排布。几何题动笔前先在本卡中找到「结论对应的定理」，再写理由，可以避免「心里知道但不会写过程」。"},{"type":"p","text":"看到什么就找哪一条：要证两条直线平行，找「三种角」的判定；要由平行得角的关系，找平行线的性质；要算长度，用两点间距离公式或中点公式；处理对称与平移，直接用坐标规律，不必画图推导。"},{"type":"p","text":"带 ★ 的是必考：带 ★ 的条目是高频点：平行线的判定与性质、垂线段最短（点到直线的距离）、余角与补角的性质、关于坐标轴对称的点的坐标规律。"},{"type":"p","text":"所有结论都有前提：本卡每一条定理都带前提（同一平面内、两直线平行、过直线外一点等），答题时漏写前提是几何题失分最多的地方：写「同位角相等」必须补上「两直线平行」。"},{"type":"note","title":"中考考法","text":"平行线判定与性质的角度计算\n解答题先由同位角、内错角、同旁内角的关系证平行，再由平行推出角的关系，推理方向不能反，「两直线平行」这一前提每步都要写明。"},{"type":"note","title":"中考考法","text":"余角、补角、对顶角与度分秒计算\n选择填空常以度分秒或倍数关系给条件求角，设未知数列方程最稳，同角或等角的余角相等、补角相等是证明两角相等的常用依据。"},{"type":"note","title":"中考考法","text":"坐标对称、平移与距离公式\n给点坐标考关于坐标轴或原点对称、按规律平移、用距离公式与中点公式计算，到坐标轴的距离要加绝对值且勿写反横、纵坐标。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["线段的中点","点 M 把线段 AB 分成两条相等的线段，则 M 是线段 AB 的中点。","判定时要同时满足「AM=MB」和「点 M 在线段 AB 上」；只说 AM=MB 不够，点可能在直线 AB 上位于线段之外。坐标形式的结论见下一条「两点间距离公式」中的中点公式。"],["两点间的距离公式与中点坐标公式","平面内两点间的距离等于横、纵坐标之差的平方和的算术平方根；中点的横、纵坐标分别是两端点横、纵坐标的平均数。","距离公式由勾股定理得到，横纵坐标相减的顺序不影响结果（平方后相同）。它在数轴上退化为 AB=|x₁-x₂|。中点坐标公式也可用来求对称点：已知一端点与中点可求另一端点。"],["角的度量与换算 ★","度、分、秒之间是六十进制：1 度等于 60 分，1 分等于 60 秒。","计算时按六十进制借位与进位，如 90^°-37^°26^()=89^°60^()-37^°26^()=52^°34^()。度分秒的加减不要把 100 当成进位单位。"],["余角的性质","两角之和为 90^° 时，这两个角互为余角；同角（或等角）的余角相等。","余角只与度数之和有关，与两角的位置无关（不需要相邻）。∠α 的余角为 90^°-∠α；「同角的余角相等」是证明两角相等的常用依据。"],["补角的性质","两角之和为 180^° 时，这两个角互为补角；同角（或等角）的补角相等。","∠α 的补角为 180^°-∠α；同一个角的补角比它的余角大 90^°。互为补角的两个角不一定相邻，相邻且互补（构成平角）的两个角叫邻补角。"],["对顶角与邻补角","两条直线相交，对顶角相等；相邻的两个角互为邻补角，它们的和是 180^°。","前提都是「两条直线相交」。相等的角不一定是对顶角（反向：对顶角一定相等）；邻补角既满足相邻，又满足互补，两个条件缺一不可。"],["垂线的性质（垂线段最短）★","在同一平面内，过一点有且只有一条直线与已知直线垂直；连接直线外一点与直线上各点的所有线段中，垂线段最短。","点到直线的距离是垂线段的长度（一个正数），不是垂线段本身；「过一点有且只有一条」的前提是「在同一平面内」。求两条平行线间的距离，就是其中一条直线上任意一点到另一条直线的垂线段长。"],["两直线平行的判定 ★","两条直线被第三条直线所截，若同位角相等，则两直线平行；若内错角相等，则两直线平行；若同旁内角互补，则两直线平行。","判定是由「角的关系」推出「线的位置关系」。同旁内角是互补（和为 180^°）而不是相等，这是最常见的记错点。另有「平行于同一直线的两直线平行」「同一平面内垂直于同一直线的两直线平行」两条判定。"],["平行线的性质 ★","两直线平行，同位角相等；两直线平行，内错角相等；两直线平行，同旁内角互补。","性质是由「线的位置关系」推出「角的关系」，与判定互为逆命题，用错方向会被判「理由不成立」。条件的顺序也要写对：「两直线平行」在句首。"],["平行公理及其推论","经过直线外一点，有且只有一条直线与这条直线平行；如果两条直线都与第三条直线平行，那么这两条直线也互相平行。","前提是「经过直线外一点」（点在直线上时没有这样的直线）。推论的作用是传递平行关系：证 a∥ c 时，找一个既有 a∥ b 又有 b∥ c 的中间直线即可。"],["平移的性质","平移不改变图形的形状和大小；连接各组对应点的线段平行（或在同一条直线上）且相等；对应线段平行且相等，对应角相等。","平移由「方向」和「距离」两个要素决定，二者缺一不可。平移前后图形全等，所以对应角相等、对应线段相等；由平移得到的两条线段一定平行（或在同一直线上），这是证明平行四边形与等积变换的常用依据。"],["各象限内点的坐标符号","第一象限 (+,+)，第二象限 (-,+)，第三象限 (-,-)，第四象限 (+,-)；x 轴上的点纵坐标为 0，y 轴上的点横坐标为 0。","原点既在 x 轴上也在 y 轴上；坐标轴上的点不属于任何象限。已知点在某象限可以据此列出不等式组求参数范围，这是「坐标 + 不等式」的常见考法。"],["关于坐标轴对称的点的坐标 ★","点 P(a,b) 关于 x 轴对称的点的坐标是 (a,-b)；关于 y 轴对称的点的坐标是 (-a,b)；关于原点对称的点的坐标是 (-a,-b)。","口诀：关于谁对称，谁不变（关于 x 轴对称横坐标不变，关于 y 轴对称纵坐标不变），关于原点对称两个坐标都变号。作图时也可用「沿哪条轴翻折」来判断。"],["点的平移规律","把点 P(a,b) 向右（左）平移 m 个单位，得到 (a+m,b)（(a-m,b)）；向上（下）平移 n 个单位，得到 (a,b+n)（(a,b-n)）。","左右平移只改变横坐标（右加左减），上下平移只改变纵坐标（上加下减），不要交叉。平移与对称复合时，按题目顺序分两步计算最稳；图形平移时每个点都按同一规律变化。"],["角平分线的定义","从一个角的顶点出发，把这个角分成两个相等的角的射线，叫这个角的平分线。","角平分线是一条射线（不是直线、不是线段），它必须从角的顶点出发。由定义可得「两个小角相等」和「大角等于小角的 2 倍」两个方向的关系，求角时不要漏掉任何一个。"],["点到坐标轴的距离","点 P(a,b) 到 x 轴的距离是 |b|，到 y 轴的距离是 |a|；点 P 到原点的距离是 √(a²+b²)。","距离非负，必须加绝对值：到 x 轴的距离是纵坐标的绝对值（不是横坐标），这一点极易写反。由「到 x 轴距离为 3」只能得到 |b|=3，即 b=±3，需要结合所在象限才能定唯一值。"]]},{"type":"note","title":"例题","text":"已知点 A(-1,2)、B(3,5)，求线段 AB 的长和中点 M 的坐标；再把点 A 向右平移 2 个单位、向下平移 3 个单位得点 C，求点 C 关于原点对称的点 D 的坐标。"},{"type":"figure","figure":{"id":"fig-m-for-jihe-li","title":"距离、中点、平移与中心对称","caption":"A、B 连线求距离与中点 M；A 向右 2、向下 3 得 C；C 关于原点对称得 D","view":"square","alt":"平面直角坐标系中，点 A 与点 B 连成线段 AB，中点为 M；从 A 按虚线箭头平移到点 C，另有一点 D 在第二象限，与 C 关于原点对称。","prims":[{"t":"plane","x":34,"y":52,"right":32,"left":22,"up":44,"down":16,"xLabel":"x","yLabel":"y","xTicks":[{"at":-8,"label":"-1"},{"at":8,"label":"1"},{"at":16,"label":"2"},{"at":24,"label":"3"}],"yTicks":[{"at":8,"label":"1"},{"at":16,"label":"2"},{"at":24,"label":"3"},{"at":32,"label":"4"},{"at":40,"label":"5"},{"at":-8,"label":"-1"}]},{"t":"line","x1":26,"y1":36,"x2":58,"y2":12,"tone":"accent","width":0.9},{"t":"arrow","x1":26,"y1":36,"x2":40,"y2":62,"dashed":true,"tone":"muted"},{"t":"line","x1":42,"y1":60,"x2":26,"y2":44,"tone":"ok","dashed":true},{"t":"dot","x":26,"y":36,"label":"A","labelDx":-5.4,"labelDy":-2.8},{"t":"dot","x":58,"y":12,"label":"B","labelDx":2.6,"labelDy":-2.8},{"t":"dot","x":42,"y":24,"label":"M","labelDx":2.6,"labelDy":2.4},{"t":"dot","x":42,"y":60,"label":"C","labelDx":2.6,"labelDy":2.4},{"t":"dot","x":26,"y":44,"label":"D","labelDx":-5.4,"labelDy":2.4},{"t":"text","x":30,"y":24,"text":"AB","anchor":"start","size":3.6,"tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["用两点间距离公式：AB=√((3-(-1))²+(5-2)²)=√(16+9)=5。","用中点坐标公式：M((-1+3)/(2),(2+5)/(2))=(1,(7)/(2))。","按平移规律「右加左减、上加下减」：A(-1,2) 向右 2 个单位、向下 3 个单位得 C(-1+2,2-3)=(1,-1)。","关于原点对称时横、纵坐标都变号，所以 D(-1,1)。"]},{"type":"p","text":"答案：AB=5，M(1,(7)/(2))，D(-1,1)"},{"type":"note","title":"方法小结","text":"坐标类题目的通用做法：先在本卡找到对应公式（距离、中点、对称、平移），再逐个代入数字。横纵坐标之差不要求定顺序（平方后相同），但平移时「右加左减、上加下减」一定不能反。"},{"type":"note","title":"例题","text":"如图，直线 a∥ b，直线 c 分别与 a、b 相交，其中 ∠ 1=65^°，∠ 2 与 ∠ 1 是同位角，∠ 3 与 ∠ 2 是邻补角。求 ∠ 2、∠ 3 的度数。"},{"type":"figure","figure":{"id":"fig-m-for-jihe-1","title":"平行线被第三条直线所截","caption":"∠1 与 ∠2 是同位角，∠2 与 ∠3 是邻补角","view":"wide","alt":"两条水平直线 a 和 b 互相平行，一条从左上到右下的直线 c 分别与 a、b 相交；在 a 与 c 的交点处标有 ∠1（65 度），在 b 与 c 的交点处标有 ∠2（与 ∠1 同位）和 ∠3（与 ∠2 互为邻补角）","prims":[{"t":"line","x1":12,"y1":28,"x2":88,"y2":28,"width":1.5},{"t":"line","x1":12,"y1":64,"x2":88,"y2":64,"width":1.5},{"t":"line","x1":28,"y1":14,"x2":58,"y2":80,"width":1.5},{"t":"text","x":90,"y":30,"text":"a","size":4,"anchor":"start"},{"t":"text","x":90,"y":66,"text":"b","size":4,"anchor":"start"},{"t":"text","x":26,"y":12,"text":"c","size":4,"anchor":"end"},{"t":"angle","x":34,"y":28,"from":0,"to":-65,"r":8,"label":"1","tone":"accent"},{"t":"angle","x":51,"y":64,"from":0,"to":-65,"r":8,"label":"2","tone":"accent"},{"t":"angle","x":51,"y":64,"from":0,"to":115,"r":8,"label":"3","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["看清已知与所求：已知两直线平行，由平行线的性质求角，推理方向是「由线到角」。","因为 a∥ b，∠ 2 与 ∠ 1 是同位角，根据「两直线平行，同位角相等」，得 ∠ 2=∠ 1=65^°。","∠ 3 与 ∠ 2 是邻补角，两角之和为 180^°，所以 ∠ 3=180^°-65^°=115^°。","检验：∠ 1 与 ∠ 3 是同旁内角，由「两直线平行，同旁内角互补」得 65^°+115^°=180^°，结果一致。"]},{"type":"p","text":"答案：∠ 2=65^°，∠ 3=115^°。"},{"type":"note","title":"方法小结","text":"由平行得到角的关系时，理由必须写成「两直线平行，同位角相等（内错角相等、同旁内角互补）」，「两直线平行」这个前提不能省略。"},{"type":"note","title":"例题","text":"计算：（1）32^° 45^() 的余角和补角；（2）180^°-65^° 28^()。"},{"type":"list","title":"解题步骤","items":["求余角：先把 90^° 写成 89^° 60^() 再相减，89^° 60^()-32^° 45^()=57^° 15^()。","求补角：把 180^° 写成 179^° 60^()，179^° 60^()-32^° 45^()=147^° 15^()。","验证补角与余角之差：147^° 15^()-57^° 15^()=90^°，符合同一个角的补角比余角大 90^°。","计算第（2）小题：179^° 60^()-65^° 28^()=114^° 32^()。"]},{"type":"p","text":"答案：（1）余角为 57^° 15^()，补角为 147^° 15^()；（2）114^° 32^()。"},{"type":"note","title":"方法小结","text":"度、分、秒是六十进制，不够减时从高一位借 1 当 60：90^° 要先化成 89^° 60^()，不能按十进制借 100。"},{"type":"list","title":"易错点","items":["平行线的判定与性质混用：由角推线要用判定，由线推角要用性质；答题时漏写「两直线平行」这个前提。","「相等的角是对顶角」「同位角相等」都缺条件：对顶角才一定相等，两直线平行时同位角才相等。","坐标平移与对称的符号写反：关于 $x$ 轴对称是纵坐标变号，向右平移是横坐标加；到 $x$ 轴的距离误写成横坐标的绝对值。","把点到直线的距离写成垂线段本身，或忽略「在同一平面内」这一前提而使用垂线与平行的结论。"]},{"type":"list","title":"解题方法","items":["几何计算题先画图、把已知条件标在图上（相等的边用短杠、相等的角用弧线），再把「角的关系」和「线段的关系」分行写出来，最后找等量关系列方程。","坐标类题目把四张小公式（距离公式、中点公式、对称规律、平移规律）直接写在草稿旁边再代数，比凭记忆推导更稳，也便于检查。","求角的度数用「设未知数列方程」：设所求角为 x^°，用 90-x 表示余角、180-x 表示补角，把题目中的倍数关系翻译成方程，比一步步推算更不容易漏情况。"]}],"questions":[{"id":"q-m-for-jihe-1","type":"choice","stem":"下列说法正确的是","answer":"C","explain":"C 是平行线的判定定理，正确。A 中相等的角不一定是对顶角（对顶角一定相等，反之不成立）；B 缺少「两直线平行」这个前提，只有两直线平行时同位角才相等；D 必须强调「过直线外一点」，且要在同一平面内。","options":["相等的两个角一定是对顶角","两条直线被第三条直线所截，同位角一定相等","同旁内角互补，两直线平行","过一点有且只有一条直线与已知直线平行"],"difficulty":2,"tags":["平行线的判定","对顶角"]},{"id":"q-m-for-jihe-2","type":"fill","stem":"点 P(-3,2) 关于 x 轴对称的点的坐标是____。","answer":"(-3,-2)","explain":"关于 x 轴对称时横坐标不变、纵坐标互为相反数，所以 P(-3,2) 的对称点为 (-3,-2)。若写成 (3,2)，则是关于 y 轴对称的点的坐标。","difficulty":1,"tags":["坐标对称"]},{"id":"q-m-for-jihe-3","type":"choice","stem":"已知点 A(1,2)、B(4,6)，则线段 AB 的长为","answer":"C","explain":"由两点间距离公式：AB=√((4-1)²+(6-2)²)=√(9+16)=5。A、D 分别是横纵坐标之差，不能直接当距离；B 是纵坐标之差。","options":["3","4","5","√(7)"],"difficulty":1,"tags":["两点间距离","勾股定理"],"figure":{"id":"fig-for-jihe-juli-q","title":"用两点间距离公式求线段长","caption":"A(1,2)、B(4,6)：横坐标之差为 3、纵坐标之差为 4，在直角三角形中用勾股定理得 AB = 5","view":"square","alt":"平面直角坐标系中标出 A(1,2) 与 B(4,6) 两点，两点连成线段 AB；从 B 向过 A 的水平线作垂线与 A 向右的虚线围成一个直角三角形，两条直角边分别标注为 3 与 4。","prims":[{"t":"plane","x":30,"y":76,"right":42,"left":20,"up":58,"down":16,"xLabel":"x","yLabel":"y","xTicks":[{"at":9,"label":"1"},{"at":18,"label":"2"},{"at":27,"label":"3"},{"at":36,"label":"4"}],"yTicks":[{"at":9,"label":"1"},{"at":18,"label":"2"},{"at":27,"label":"3"},{"at":36,"label":"4"},{"at":45,"label":"5"},{"at":54,"label":"6"}]},{"t":"line","x1":37,"y1":62,"x2":58,"y2":34,"tone":"accent","width":0.9},{"t":"line","x1":37,"y1":62,"x2":58,"y2":62,"tone":"muted","dashed":true},{"t":"line","x1":58,"y1":62,"x2":58,"y2":34,"tone":"muted","dashed":true},{"t":"line","x1":54,"y1":62,"x2":54,"y2":58,"tone":"muted"},{"t":"line","x1":54,"y1":58,"x2":58,"y2":58,"tone":"muted"},{"t":"dot","x":37,"y":62,"label":"A","labelDx":-6,"labelDy":2.8},{"t":"dot","x":58,"y":34,"label":"B","labelDx":3,"labelDy":-1.4},{"t":"text","x":47.5,"y":57,"text":"3","anchor":"middle","size":3.6,"tone":"muted"},{"t":"text","x":61,"y":48,"text":"4","anchor":"start","size":3.6,"tone":"muted"},{"t":"text","x":56,"y":34,"text":"AB = ?","anchor":"start","size":3.6,"tone":"danger"}]}},{"id":"q-m-for-jihe-4","type":"short","stem":"一个角的补角比它的余角的 2 倍还大 30^°，求这个角的度数。","answer":"设这个角为 $x^\\circ$，则它的补角为 $180-x$，余角为 $90-x$。依题意得 $180-x=2(90-x)+30$，化简得 $180-x=210-2x$，解得 $x=30$。所以这个角是 $30^\\circ$。","explain":"关键在于用同一未知数表示补角与余角：补角是 180-x，余角是 90-x（只有锐角才有余角，x=30 满足）。解方程：180-x=180-2x+30，即 -x=-2x+30，得 x=30。检验：补角 150^°，余角 60^°，2×60+30=150，符合题意。","difficulty":2,"tags":["余角与补角","列方程求角"],"rubric":["设所求角为 x^°，并正确写出补角 180-x 与余角 90-x","列出方程 180-x=2(90-x)+30","正确解得 x=30","检验：30^° 是锐角，既有余角也有补角，结果符合题意"]},{"id":"q-m-for-jihe-z1","type":"choice","stem":"若点 P(a,b) 在第二象限，则点 Q(-a,b) 在","answer":"A","explain":"点 P(a,b) 在第二象限，说明 a<0，b>0。于是 -a>0，点 Q(-a,b) 的横、纵坐标都为正，即 (+,+)，所以点 Q 在第一象限。","options":["第一象限","第二象限","第三象限","第四象限"],"difficulty":2,"tags":["平面直角坐标系","象限"]},{"id":"q-m-for-jihe-z2","type":"fill","stem":"点 M(-4,3) 到原点的距离是____。","answer":"5","explain":"点 P(a,b) 到原点的距离为 √(a²+b²)，所以点 M(-4,3) 到原点的距离为 √((-4)²+3²)=√(16+9)=√(25)=5。注意平方后负号消去，不要误算成 √(-16+9)。","difficulty":2,"tags":["点的坐标","两点间距离"]}]},{"id":"m-for-sanjiao","title":"三角形与四边形性质速查","subtitle":"速查 · 三角形与四边形","grade":"all","tags":["公式与定理","三角形与四边形"],"blocks":[{"type":"note","title":"教材章节","text":"速查 · 三角形与四边形"},{"type":"note","title":"一句话概述","text":"三角形（全等、等腰、勾股定理）与四边形（平行四边形及其特殊情形、多边形内角和）的定理集中速查，是证明题与计算题的核心武器库。"},{"type":"h","text":"核心概念"},{"type":"p","text":"本卡怎么用：按「三角形的基本关系 → 全等三角形 → 等腰与等边三角形 → 垂直平分线与角平分线 → 勾股定理 → 多边形内角和 → 四种特殊平行四边形」排布，证明题先定结论类型，再回本卡找对应的判定定理。"},{"type":"p","text":"看到什么就找哪一条：证线段或角相等：优先全等三角形，其次三角形中位线、线段垂直平分线、等腰三角形；算长度：在直角三角形中用勾股定理，或使用「斜边中线等于斜边一半」「30^° 角所对的直角边等于斜边一半」；证四边形是特殊的平行四边形：先证平行四边形，再加特殊条件。"},{"type":"p","text":"带 ★ 的是必考：带 ★ 的条目是高频点：全等三角形的五种判定、等腰三角形「三线合一」、勾股定理及其逆定理、平行四边形与矩形、菱形、正方形的判定。"},{"type":"p","text":"判定与性质成对记忆：本卡多数条目都是「判定 + 性质」的一对（等腰三角形、垂直平分线、角平分线、勾股定理、平行四边形、矩形、菱形、正方形）。用哪一条取决于已知：已知图形具有某性质就用性质，要证明它具有某性质就用判定。"},{"type":"p","text":"关于梯形：现行人教版教材中梯形不作独立一节，但中考四边形综合题仍常以「一组对边平行」的形式出现，掌握三条常用辅助线（过顶点作高、平移一腰、延长两腰交于一点）即可应付。"},{"type":"note","title":"中考考法","text":"全等三角形的判定与证明\n解答题高频题位，从 SSS、SAS、ASA、AAS、HL 中选判定并写出三个条件，对应顶点字母写在对应位置，再由全等得对应边、对应角相等。"},{"type":"note","title":"中考考法","text":"等腰三角形与勾股定理综合\n三线合一常把等腰三角形问题化为直角三角形问题，再用勾股定理求高或面积；已知两边求周长要分类讨论并用三边关系取舍。"},{"type":"note","title":"中考考法","text":"特殊平行四边形的判定与性质\n证明按「先证平行四边形、再补特殊条件」的顺序进行，矩形看直角与对角线相等，菱形看邻边相等与对角线垂直平分。"},{"type":"note","title":"中考考法","text":"多边形角和与三角形中位线\n用 (n-2)× 180^° 求边数或内角，外角和恒为 360^°；见两边中点想中位线，平行与等于第三边一半两个结论都要写出。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["三角形三边关系","三角形任意两边之和大于第三边，任意两边之差小于第三边。","判断三条线段能否组成三角形，只需检验「较短的两条边之和是否大于最长边」（另外两个不等式自动成立）。已知两边长 b、c 求第三边 a 的范围时用 |b-c|<a<b+c，两端都不含等号：等于时三点共线，不能构成三角形。"],["三角形内角和定理","三角形三个内角的和等于 180^°。","对任意形状的三角形都成立。它是多边形内角和公式 (n-2)×180^° 的基础；由它可以得到「直角三角形的两个锐角互余」和「三角形中至少有两个锐角」。"],["三角形的外角性质","三角形的一个外角等于与它不相邻的两个内角的和；三角形的一个外角大于与它不相邻的任何一个内角。","必须是「不相邻」的两个内角：外角与它相邻的内角是邻补角（和为 180^°），不要混用。「外角大于不相邻内角」只用于比较角的大小（证明不等关系），不能用来求角的度数。"],["三角形中位线定理 ★","连接三角形两边中点的线段叫三角形的中位线，它平行于第三边，并且等于第三边的一半。","中位线是「两边中点的连线」，不要与「中线」（顶点与对边中点的连线）混淆。一个三角形有三条中位线。见中点想中位线：需要证明平行或需要「一半」的线段关系时，中位线是首选辅助线。"],["全等三角形的判定（SSS、SAS、ASA、AAS、HL）★","三边分别相等（SSS）；两边和它们的夹角分别相等（SAS）；两角和它们的夹边分别相等（ASA）；两角和其中一角的对边分别相等（AAS）；斜边和一条直角边分别相等（HL，只适用于直角三角形）。","没有 SSA，也没有 AAA：两边及其中一边的对角分别相等不能判定全等（可能出现两种图形），三个角分别相等只能判定相似。SAS 中的角必须是两边的夹角。HL 只用于直角三角形，且必须写成「斜边、直角边」的顺序。"],["全等三角形的性质","全等三角形的对应边相等，对应角相等；对应边上的中线、高线和对应角的平分线都相等；周长相等，面积相等。","书写时必须把对应顶点的字母写在对应位置，如 △ ABC≌△ DEF 表示 A 与 D、B 与 E、C 与 F 对应，据此才能正确读出对应边和对应角。反之，面积相等或周长相等的两个三角形不一定全等。"],["等腰三角形的性质（等边对等角、三线合一）★","等腰三角形的两个底角相等（等边对等角）；顶角平分线、底边上的中线、底边上的高互相重合（三线合一）。","「等边对等角」要求两条相等的边在同一个三角形中。三线合一指的是「顶角的平分线、底边上的中线、底边上的高」这三条线互相重合（不是腰上的中线或高）。已知等腰三角形的一边求边长时，要分「已知边是腰」和「已知边是底」两种情况讨论，并用三边关系检验取舍。"],["等腰三角形的判定（等角对等边）","有两个角相等的三角形是等腰三角形（等角对等边）；有两边相等的三角形是等腰三角形。","「等角对等边」用于判定，「等边对等角」用于性质，方向相反不要写反。两个角必须同在一个三角形中；证明两边相等时，先找到这两边所对的两个角相等即可。"],["等边三角形的性质与判定","性质：等边三角形的三条边相等，三个内角都等于 60^°。判定：三条边都相等的三角形是等边三角形；三个角都相等的三角形是等边三角形；有一个角是 60^° 的等腰三角形是等边三角形。","等边三角形是特殊的等腰三角形，等腰三角形的一切性质都适用。特别注意最后一条判定必须同时有「等腰」和「60^°」两个条件：有一个角是 60^° 的普通三角形（如 60^°、40^°、80^°）不是等边三角形。"],["线段垂直平分线的性质与判定 ★","线段垂直平分线上的点与这条线段两个端点的距离相等；反过来，与线段两个端点距离相等的点，在这条线段的垂直平分线上。","垂直平分线是一条直线，必须同时满足「过线段中点」和「垂直于线段」两个条件。判定方向（由 PA=PB 推出点在垂直平分线上）常用于证明垂直或求作点；作图题中「到两点距离相等」的点必在垂直平分线上、进而想到「外心」。"],["角平分线的性质与判定 ★","角平分线上的点到角两边的距离相等；反过来，角的内部到角两边距离相等的点，在这个角的平分线上。","「距离」指到两边的垂线段长，所以图中必须有垂直（作垂线才能用）。判定定理要求点在角的内部，否则可能是外角平分线上的点。利用角平分线求面积或作辅助线时，第一反应就是「作两边的垂线」。"],["勾股定理及其逆定理 ★","直角三角形两条直角边的平方和等于斜边的平方；反过来，如果三角形的三边满足 a²+b²=c²，那么这个三角形是直角三角形，且边 c 所对的角是直角。","公式中的 c 一定是斜边（最长边），用公式前先分清直角边和斜边，否则会把 c²=a²+b² 用成 b²=a²+c²。逆定理是「由数量关系判定形状」，必须先算出三边的平方关系再下结论，写作时要点明「最长边所对的角是直角」。常用勾股数：3,4,5；5,12,13；8,15,17；7,24,25，以及它们的整数倍（如 6,8,10）。"],["直角三角形斜边上的中线定理 ★","直角三角形斜边上的中线等于斜边的一半（D 为斜边 AB 的中点）。","只对直角三角形成立，条件是「斜边上的中线」。由此可得斜边中点到三角形三个顶点的距离相等（即直角三角形的外心是斜边的中点，斜边是外接圆的直径）。见「直角 + 中点」时优先考虑这条定理。"],["含 30° 角的直角三角形","在直角三角形中，如果一个锐角等于 30^°，那么它所对的直角边等于斜边的一半。","必须同时满足「直角三角形」和「30^° 角」，且是 30^° 角「所对」的那条直角边。反过来也成立：若一条直角边等于斜边的一半，则它所对的角是 30^°。不要与「斜边上的中线等于斜边的一半」混淆：前者限定 30^° 角的对边，后者限定斜边上的中线。"],["多边形内角和与外角和 ★","n（n≥3，n 为整数）边形的内角和等于 (n-2)×180^°；任意多边形的外角和都等于 360^°。","外角和与边数无关，永远等于 360^°（这是求边数最快的入口）。正 n 边形的每个内角为 ((n-2)×180^°)/(n)，每个外角为 (360^°)/(n)。已知内角和求边数时列方程 (n-2)×180^°=…，解得 n 必须是不小于 3 的整数，否则题目条件有误。"],["平行四边形的性质与判定 ★","性质：平行四边形的两组对边分别平行且相等，两组对角分别相等，两条对角线互相平分。判定：两组对边分别平行的四边形是平行四边形；两组对边分别相等的四边形是平行四边形；一组对边平行且相等的四边形是平行四边形；两条对角线互相平分的四边形是平行四边形。","判定与性质互为逆命题，先看已知是「平行四边形」还是「要证平行四边形」再选。特别注意：「一组对边平行、另一组对边相等」不能判定平行四边形（等腰梯形就是反例），必须写成「一组对边平行且相等」。"],["矩形的性质与判定 ★","性质：矩形的四个角都是直角，两条对角线相等且互相平分。判定：有一个角是直角的平行四边形是矩形；对角线相等的平行四边形是矩形；有三个角是直角的四边形是矩形。","矩形的对角线相等但不一定互相垂直（对角线互相垂直是菱形的特征）。「对角线相等的四边形」不一定是矩形（等腰梯形就是反例），必须加上「平行四边形」或「三个角是直角」的条件。"],["菱形的性质与判定（含面积公式）★","性质：菱形的四条边都相等，两条对角线互相垂直平分，并且每一条对角线平分一组对角。判定：有一组邻边相等的平行四边形是菱形；对角线互相垂直的平行四边形是菱形；四条边都相等的四边形是菱形。面积可用两条对角线乘积的一半计算。","菱形面积有两种算法：底乘对应的高，以及两条对角线乘积的一半（已知对角线时用后者最快）。「对角线互相垂直平分的四边形是菱形」中的「平分」不能少：只垂直不平分不能判定菱形。菱形是轴对称图形，两条对角线所在直线都是它的对称轴。"],["正方形的性质与判定 ★","正方形既是矩形又是菱形：四条边都相等，四个角都是直角，两条对角线相等且互相垂直平分，每条对角线平分一组对角，对角线与边的夹角为 45^°。判定：有一组邻边相等且有一个角是直角的平行四边形是正方形；既是矩形又是菱形的四边形是正方形。","证明思路是「先证平行四边形，再加两组条件」：先证矩形再证邻边相等，或先证菱形再证有一个角是直角。正方形具有矩形和菱形的全部性质，面积 S=a²（a 为边长），也可用对角线长 d 表示为 S=(1)/(2)d²；对角线长 d=√(2)a。"],["梯形与等腰梯形","一组对边平行、另一组对边不平行的四边形叫梯形；两腰相等的梯形叫等腰梯形，等腰梯形在同一底上的两个角相等，两条对角线相等。梯形的中位线平行于两底，并且等于两底和的一半，即 l=(1)/(2)(a+b)；梯形面积等于上、下底之和与高的乘积的一半。","梯形的中位线公式与三角形中位线（等于第三边的一半）形式不同，不要混用。等腰梯形的性质必须是「同一底上的两个角」，跨底的两个角只互补不相等。常用辅助线：过顶点作高、平移一腰、延长两腰交于一点，把梯形问题化为三角形或平行四边形问题。"]]},{"type":"note","title":"例题","text":"在 △ ABC 中，AB=AC=5，BC=8，D 为 BC 的中点。求 AD 的长和 △ ABC 的面积。"},{"type":"figure","figure":{"id":"fig-m-for-sanjiao-e1","title":"等腰三角形三线合一后解直角三角形","caption":"AB=AC=5、BC=8，D 是 BC 的中点：AD 也是底边上的高（D 处画直角方框），BD=DC=4，在 Rt△ABD 中求 AD","view":"square","alt":"等腰三角形 ABC，两腰 AB 与 AC 标注为 5，底边 BC 标注为 8；D 是 BC 的中点，AD 是底边上的高，D 处画有直角方框，BD 与 DC 画有相同的等长记号。","prims":[{"t":"poly","points":[[50,12],[22,54],[78,54]],"closed":true},{"t":"line","x1":50,"y1":12,"x2":50,"y2":54,"tone":"accent"},{"t":"line","x1":50,"y1":50.5,"x2":46.5,"y2":50.5,"tone":"muted"},{"t":"line","x1":46.5,"y1":50.5,"x2":46.5,"y2":54,"tone":"muted"},{"t":"line","x1":37.25,"y1":33.83,"x2":34.75,"y2":32.17,"tone":"ok"},{"t":"line","x1":65.25,"y1":32.17,"x2":62.75,"y2":33.83,"tone":"ok"},{"t":"line","x1":34.8,"y1":52.5,"x2":34.8,"y2":55.5,"tone":"ok"},{"t":"line","x1":37.2,"y1":52.5,"x2":37.2,"y2":55.5,"tone":"ok"},{"t":"line","x1":62.8,"y1":52.5,"x2":62.8,"y2":55.5,"tone":"ok"},{"t":"line","x1":65.2,"y1":52.5,"x2":65.2,"y2":55.5,"tone":"ok"},{"t":"text","x":32,"y":32,"text":"5","anchor":"end","size":3.6,"tone":"muted"},{"t":"text","x":68,"y":32,"text":"5","anchor":"start","size":3.6,"tone":"muted"},{"t":"text","x":36,"y":49,"text":"4","anchor":"middle","size":3.6,"tone":"muted"},{"t":"text","x":64,"y":49,"text":"4","anchor":"middle","size":3.6,"tone":"muted"},{"t":"text","x":53,"y":34,"text":"AD = ?","anchor":"start","size":3.6,"tone":"danger"},{"t":"dot","x":50,"y":12,"label":"A","labelDx":-1.2,"labelDy":-2.8},{"t":"dot","x":22,"y":54,"label":"B","labelDx":-5.4,"labelDy":2.4},{"t":"dot","x":78,"y":54,"label":"C","labelDx":2.2,"labelDy":2.4},{"t":"dot","x":50,"y":54,"label":"D","labelDx":-1.2,"labelDy":2.4}]}},{"type":"list","title":"解题步骤","items":["由 AB=AC 知 △ ABC 是等腰三角形，D 为底边 BC 的中点。由等腰三角形「三线合一」可知 AD 也是底边 BC 上的高，所以 AD⊥ BC。","于是 BD=(1)/(2)BC=4，在 Rt△ ABD 中用勾股定理：AD=√(AB²-BD²)=√(25-16)=3。","求面积：S_(△ ABC)=(1)/(2)× BC× AD=(1)/(2)×8×3=12。"]},{"type":"p","text":"答案：AD=3，S_(△ ABC)=12"},{"type":"note","title":"方法小结","text":"等腰三角形已知底边求高（或已知两腰求面积）的标准套路：用「三线合一」把已知条件集中到一个直角三角形里，再用勾股定理求出未知的边。本卡中「等腰三角形的性质」和「勾股定理」几乎总是连在一起用。"},{"type":"note","title":"例题","text":"如图，在 △ ABC 中，AB=AC，AD 平分 ∠ BAC，交 BC 于点 D。求证：BD=CD。"},{"type":"figure","figure":{"id":"fig-m-for-sanjiao-2","title":"等腰三角形顶角平分线","caption":"AB=AC，AD 平分 ∠BAC，可证 △ABD≅△ACD","view":"square","alt":"等腰三角形 ABC，AB 与 AC 相等，A 在上方、BC 水平在下方；从 A 引出线段 AD 交 BC 于 D，AD 平分顶角 ∠BAC，∠BAD 与 ∠CAD 各用一段弧标出","prims":[{"t":"poly","points":[[22,72],[50,18],[78,72]],"closed":true,"tone":"main"},{"t":"line","x1":50,"y1":18,"x2":50,"y2":72,"tone":"accent"},{"t":"angle","x":50,"y":18,"from":243,"to":270,"r":10,"tone":"accent"},{"t":"angle","x":50,"y":18,"from":270,"to":298,"r":10,"tone":"accent"},{"t":"text","x":50,"y":14,"text":"A","size":4,"anchor":"middle"},{"t":"text","x":18,"y":75,"text":"B","size":4,"anchor":"end"},{"t":"text","x":82,"y":75,"text":"C","size":4,"anchor":"start"},{"t":"text","x":50,"y":78,"text":"D","size":4,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["由 AD 平分 ∠ BAC，根据角平分线的定义，得 ∠ BAD=∠ CAD。","在 △ ABD 和 △ ACD 中列出三个条件：AB=AC（已知），∠ BAD=∠ CAD（已证），AD=AD（公共边）。","两边及其夹角对应相等，根据 SAS 判定，得 △ ABD≌△ ACD。","由全等三角形的对应边相等，得 BD=CD。"]},{"type":"p","text":"答案：由 AB=AC、∠ BAD=∠ CAD、AD=AD，根据 SAS 得 △ ABD≌△ ACD，故 BD=CD。"},{"type":"note","title":"方法小结","text":"证明题书写全等要「摆条件、写依据」：把三组对应相等按判定方法的顺序列出，并用大括号括起来；AD=AD 是公共边，不能漏写。"},{"type":"note","title":"例题","text":"如图，菱形 ABCD 的两条对角线 AC、BD 相交于点 O，且 AC=6，BD=8。求菱形的边长和面积。"},{"type":"figure","figure":{"id":"fig-m-for-sanjiao-1","title":"菱形的对角线互相垂直平分","caption":"AC=6 则 OA=3，BD=8 则 OB=4，△AOB 是直角三角形","view":"square","alt":"菱形 ABCD，对角线 AC 水平、BD 竖直，交于点 O；OA 长 3，OB 长 4，两条对角线在 O 处互相垂直，形成四个全等的直角三角形","prims":[{"t":"poly","points":[[29,50],[50,22],[71,50],[50,78]],"closed":true,"tone":"main"},{"t":"line","x1":29,"y1":50,"x2":71,"y2":50,"dashed":true,"tone":"muted"},{"t":"line","x1":50,"y1":22,"x2":50,"y2":78,"dashed":true,"tone":"muted"},{"t":"angle","x":50,"y":50,"from":0,"to":90,"right":true,"r":5,"tone":"muted"},{"t":"dot","x":50,"y":50,"r":1,"tone":"muted"},{"t":"text","x":24,"y":53,"text":"A","size":4,"anchor":"end"},{"t":"text","x":50,"y":16,"text":"B","size":4,"anchor":"middle"},{"t":"text","x":76,"y":53,"text":"C","size":4,"anchor":"start"},{"t":"text","x":50,"y":84,"text":"D","size":4,"anchor":"middle"},{"t":"text","x":52,"y":53,"text":"O","size":3.6,"anchor":"start","tone":"muted"},{"t":"text","x":39,"y":47,"text":"3","size":3.6,"anchor":"middle","tone":"accent"},{"t":"text","x":53,"y":37,"text":"4","size":3.6,"anchor":"start","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["由菱形的性质，两条对角线互相垂直平分，所以 AC⊥ BD，且 OA=(1)/(2)AC=3，OB=(1)/(2)BD=4。","在 Rt△ AOB 中，由勾股定理得 AB=√(OA²+OB²)=√(3²+4²)=√(25)=5，即菱形的边长为 5。","菱形面积等于两条对角线乘积的一半：S=(1)/(2)AC· BD=(1)/(2)× 6× 8=24。","用「四个直角三角形面积之和」验证：4×(1)/(2)× 3× 4=24，结果一致。"]},{"type":"p","text":"答案：菱形的边长为 5，面积为 24。"},{"type":"note","title":"方法小结","text":"菱形对角线互相垂直平分，把菱形分成四个全等的直角三角形，求边长用勾股定理；已知两条对角线时，面积直接用 (1)/(2)× 两条对角线之积。"},{"type":"list","title":"易错点","items":["全等判定中出现「SSA」或「AAA」；SAS 的角必须是两边的夹角；HL 只能用于直角三角形。","等腰三角形已知两边求周长时不检验三边关系，把不成立的组合也算作答案（如腰长为 4、底边为 9 时，$4+4<9$ 不能构成三角形）。","把「对角线相等的平行四边形是矩形」错写成「对角线相等的四边形是矩形」；把「对角线互相垂直的四边形」当成菱形（漏掉「平分」）。","误以为「有一个角是 $60^\\circ$ 的三角形是等边三角形」，必须补上「等腰」这一条件。"]},{"type":"list","title":"解题方法","items":["证明题反向找定理：证线段或角相等优先考虑全等三角形，其次三角形中位线、线段垂直平分线、等腰三角形；证垂直优先考虑等腰三角形「三线合一」与勾股定理的逆定理。","辅助线口诀：见中点想中位线（或斜边上的中线），见角平分线想作两边的垂线，见直角想斜边中线或 30^° 角的边角关系，见切线（圆）想连半径。","特殊平行四边形一律按「先证平行四边形，再补特殊条件」的顺序证明，比直接证四边形更省步骤；性质与判定成对使用，取决于题目已知什么、要证什么。"]}],"questions":[{"id":"q-m-for-sanjiao-1","type":"choice","stem":"下列各组线段中，不能构成直角三角形的是","answer":"D","explain":"检验最长边的平方是否等于另外两边平方和：6²+8²=100=10²，5²+12²=169=13²，8²+15²=289=17²，都能构成直角三角形；而 4²+5²=41≠6²=36，所以 4,5,6 只能构成锐角三角形。","options":["6,8,10","5,12,13","8,15,17","4,5,6"],"difficulty":1,"tags":["勾股定理逆定理","勾股数"]},{"id":"q-m-for-sanjiao-2","type":"fill","stem":"一个多边形的内角和是 1080^°，则它的边数是____。","answer":"8","explain":"设边数为 n，由内角和公式得 (n-2)×180^°=1080^°，所以 n-2=6，n=8，即这个多边形是八边形。","difficulty":1,"tags":["多边形内角和"]},{"id":"q-m-for-sanjiao-3","type":"choice","stem":"已知等腰三角形的一边长为 4，另一边长为 9，则它的周长是","answer":"B","explain":"需分类讨论：若腰长为 4、底边为 9，则 4+4=8<9，不能构成三角形，舍去；若腰长为 9、底边为 4，则 9+4>9 成立，周长为 9+9+4=22。所以周长只能是 22。","options":["17","22","17 或 22","无法确定"],"difficulty":2,"tags":["等腰三角形","三边关系","分类讨论"]},{"id":"q-m-for-sanjiao-4","type":"short","stem":"在 △ ABC 中，D、E 分别是边 AB、AC 的中点，BC=8，∠ B=50^°。求 DE 的长和 ∠ ADE 的度数。","answer":"$DE$ 是 $\\triangle ABC$ 的中位线，由中位线定理得 $DE\\parallel BC$ 且 $DE=\\frac{1}{2}BC=4$；由 $DE\\parallel BC$ 得同位角 $\\angle ADE=\\angle B=50^\\circ$。","explain":"D、E 分别是 AB、AC 的中点，所以 DE 是中位线。中位线定理给出两条结论：位置关系（DE∥ BC）和数量关系（DE=(1)/(2)BC=4）。由平行得到角的关系时要用「两直线平行，同位角相等」：∠ ADE 与 ∠ B 是直线 AB 截 DE、BC 所得的同位角，所以 ∠ ADE=∠ B=50^°。","difficulty":2,"tags":["三角形中位线","平行线的性质"],"rubric":["指出 DE 是 △ ABC 的中位线","由中位线定理得 DE=(1)/(2)BC=4","由 DE∥ BC 得同位角 ∠ ADE=∠ B","得出 ∠ ADE=50^°，理由写完整"],"figure":{"id":"fig-m-for-sanjiao-q4","title":"中位线 DE 与底边 BC","caption":"D、E 分别是 AB、AC 的中点：DE∥BC（两处画有平行箭头）且 DE 等于 BC 的一半；∠ADE 与 ∠B 是同位角","view":"wide","alt":"三角形 ABC，D 是 AB 的中点、E 是 AC 的中点，连接 DE；DE 与 BC 上画有平行的箭头，BC 标注为 8，顶点 B 处的角标为 50 度。","prims":[{"t":"poly","points":[[10,52],[90,52],[30,12]],"closed":true},{"t":"line","x1":50,"y1":52,"x2":20,"y2":32,"tone":"accent"},{"t":"line","x1":30,"y1":50.5,"x2":30,"y2":53.5,"tone":"ok"},{"t":"line","x1":70,"y1":50.5,"x2":70,"y2":53.5,"tone":"ok"},{"t":"line","x1":13.12,"y1":42.4,"x2":15.8,"y2":43.74,"tone":"ok"},{"t":"line","x1":14.2,"y1":40.26,"x2":16.88,"y2":41.6,"tone":"ok"},{"t":"line","x1":23.12,"y1":22.4,"x2":25.8,"y2":23.74,"tone":"ok"},{"t":"line","x1":24.2,"y1":20.26,"x2":26.88,"y2":21.6,"tone":"ok"},{"t":"poly","points":[[37.41,41.81],[34.58,41.72],[35.75,44.3]],"tone":"accent"},{"t":"poly","points":[[62.41,31.81],[59.58,31.72],[60.75,34.3]],"tone":"accent"},{"t":"angle","x":90,"y":52,"from":-180,"to":-213.69,"r":8,"tone":"ok","label":"50°"},{"t":"text","x":65,"y":30,"text":"BC = 8","anchor":"start","size":3.6,"tone":"muted"},{"t":"text","x":27,"y":45,"text":"DE = ?","anchor":"end","size":3.6,"tone":"danger"},{"t":"dot","x":10,"y":52,"label":"A","labelDx":-5.4,"labelDy":2.4},{"t":"dot","x":90,"y":52,"label":"B","labelDx":2.2,"labelDy":2.4},{"t":"dot","x":30,"y":12,"label":"C","labelDx":-5.4,"labelDy":-2.8},{"t":"dot","x":50,"y":52,"label":"D","labelDx":2.2,"labelDy":2.4},{"t":"dot","x":20,"y":32,"label":"E","labelDx":-5.4,"labelDy":-2.8}]}},{"id":"q-m-for-sanjiao-z1","type":"choice","stem":"下列命题中，正确的是","answer":"D","explain":"矩形的四个角都是直角，若再有一组邻边相等，则四条边都相等，它同时是菱形，也就是正方形，D 正确。A、B 都漏掉了「平行四边形」这个前提，等腰梯形的对角线相等、但不是矩形，A 为假命题；C 也可能是等腰梯形，不能判定为平行四边形。","options":["对角线相等的四边形是矩形","对角线互相垂直的四边形是菱形","一组对边平行、另一组对边相等的四边形是平行四边形","一组邻边相等的矩形是正方形"],"difficulty":2,"tags":["矩形菱形正方形","判定定理"]},{"id":"q-m-for-sanjiao-z2","type":"fill","stem":"一个直角三角形的两条直角边长分别为 5 和 12，则它斜边上的中线长为____。","answer":"6.5|13/2|\\frac{13}{2}","explain":"先由勾股定理求斜边：c=√(5²+12²)=√(25+144)=13。直角三角形斜边上的中线等于斜边的一半，所以斜边上的中线长为 (13)/(2)=6.5。","difficulty":2,"tags":["直角三角形","斜边中线"]}]},{"id":"m-for-yuan","title":"圆与三角函数速查","subtitle":"速查 · 圆与三角函数","grade":"all","tags":["公式与定理","圆与三角函数"],"blocks":[{"type":"note","title":"教材章节","text":"速查 · 圆与三角函数"},{"type":"note","title":"一句话概述","text":"圆的定理（垂径、圆周角、切线）与锐角三角函数（定义、特殊角值、解直角三角形）集中速查，是九年级考试压轴题的常客。"},{"type":"h","text":"核心概念"},{"type":"p","text":"本卡怎么用：前半部分按「圆的性质 → 位置关系 → 弧长扇形 → 圆锥」排布，后半部分按「三角函数定义 → 特殊角 → 同角关系 → 解直角三角形 → 实际应用」排布。圆中求长度看垂径定理与切线，求角度看圆周角定理。"},{"type":"p","text":"看到什么就找哪一条：圆中求弦长或弦心距：连半径、作垂线，用垂径定理配勾股定理；圆中求角：找同弧所对的圆周角或圆心角；出现切线：连切点与圆心得垂直，或由圆外一点引两条切线用切线长定理；直角三角形的边角关系：用锐角三角函数或勾股定理。"},{"type":"p","text":"带 ★ 的是必考：带 ★ 的条目是高频点：垂径定理、圆周角定理及推论、切线的判定与性质、弧长公式与扇形面积公式（含圆锥侧面展开）、特殊角的三角函数值。"},{"type":"p","text":"特殊角必须无条件记住：30^°、45^°、60^° 的正弦、余弦、正切值必须牢记，考试中不查表；同时记住 3,4,5 型与 1,1,√(2)、1,√(3),2 型直角三角形的边比，可以大幅提速。"},{"type":"note","title":"中考考法","text":"垂径定理与圆周角定理的计算\n求弦长、弦心距用「连半径、作垂线」配勾股定理，求角用同弧所对圆周角等于圆心角的一半，点在哪段弧上要看清。"},{"type":"note","title":"中考考法","text":"切线的判定、性质与切线长\n证切线用「连半径证垂直」或「作垂直证半径」，已知切线先连切点半径，圆外一点引两条切线时切线长相等、连线平分夹角。"},{"type":"note","title":"中考考法","text":"弧长、扇形面积与圆锥侧面展开\n弧长公式分母 180、扇形面积分母 360 不能混，扇形半径是母线长，求展开图圆心角用底面周长等于扇形弧长列方程。"},{"type":"note","title":"中考考法","text":"解直角三角形的实际应用\n仰角俯角、坡度、方向角问题先画水平线、构造直角三角形，按「有斜用弦、无斜用切」选函数，结果要回到实际情境检验。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["垂径定理及其推论 ★","垂直于弦的直径平分这条弦，并且平分弦所对的两条弧。推论：平分弦（不是直径）的直径垂直于这条弦，并且平分弦所对的两条弧。","条件是「直径（或过圆心的直线）垂直于弦」。推论中被平分的弦不能是直径（两条直径互相平分但不一定垂直）。计算时把半径 R、弦心距 d、半弦长 (a)/(2) 放在同一个直角三角形里：R²=d²+((a)/(2))²，这是圆中求长度最常用的关系式。"],["圆心角、弧、弦之间的关系","在同圆或等圆中，如果两个圆心角、两条弧、两条弦中有一组量相等，那么它们所对应的其余各组量都分别相等。","前提是「在同圆或等圆中」，半径不同的两个圆之间不成立。圆心角的度数等于它所对的弧的度数；同一个圆中，较大的圆心角所对的弦与弧也较大。"],["圆周角定理及推论 ★","一条弧所对的圆周角等于它所对的圆心角的一半。推论：同弧或等弧所对的圆周角相等；半圆（或直径）所对的圆周角是直角，90^° 的圆周角所对的弦是直径。","圆周角的顶点必须在圆上、两边都与圆相交。方向不要记反：圆周角是圆心角的一半（不是 2 倍）。「直径所对的圆周角是直角」与「90^° 的圆周角所对的弦是直径」要成对使用；已知圆周角求圆心角、或反之，都要先看清所对的是哪一条弧。"],["圆内接四边形的性质","圆内接四边形的对角互补。","条件是四边形的四个顶点都在圆上（内接于圆），否则不成立。常用结论：圆内接四边形的一个外角等于它的内对角，如四边形 ABCD 内接于圆，延长 BC 到 E，则 ∠ DCE=∠ A。"],["切线的判定定理 ★","经过半径的外端并且垂直于这条半径的直线是圆的切线。","两个条件缺一不可：直线经过半径的外端，且与这条半径垂直。两种常用证法：①已知直线与圆有公共点，连接圆心与公共点（连半径），再证垂直；②不确定有无公共点，过圆心作直线的垂线，再证垂线段长等于半径。"],["切线的性质定理 ★","圆的切线垂直于过切点的半径。","使用时要先连接圆心与切点（「连半径」是圆中证垂直的第一辅助线）。由此可知圆心到切线的距离等于半径，切线与圆只有一个公共点。切线垂直于过切点的半径，但不垂直于其他半径。"],["切线长定理 ★","从圆外一点引圆的两条切线，它们的切线长相等，并且这一点和圆心的连线平分两条切线的夹角。","前提是两条切线由同一个圆外一点引出。切线长是切点与圆外点之间线段的长度（不是弧长，也不是切线的全长）。由 PA=PB、OA=OB 可知直线 OP 是弦 AB 的垂直平分线，这是求弦长或证明垂直的常用结论。"],["三角形的外心与内心","外心是三角形三条边的垂直平分线的交点，它到三角形三个顶点的距离相等，是三角形外接圆的圆心；内心是三角形三条角平分线的交点，它到三角形三条边的距离相等，是三角形内切圆的圆心。","外心可能在三角形外部（钝角三角形），内心一定在三角形内部。直角三角形的外心是斜边的中点，斜边就是外接圆的直径（外接圆半径 R=(c)/(2)，c 为斜边）。内切圆半径公式 r=(2S)/(a+b+c)（S 为三角形面积）属拓展结论，由面积分割法得到，已知面积与周长时使用。"],["点、直线与圆的位置关系","设圆心到直线的距离为 d、圆的半径为 r：d>r 时直线与圆相离（无公共点）；d=r 时直线与圆相切（一个公共点）；d<r 时直线与圆相交（两个公共点）。点与圆的位置关系同理，d 换成点到圆心的距离。","d 是圆心到直线的距离，需要作垂线才能得到。三个量 d、r、位置关系知道其中两个可求第三个；「直线与圆有两个公共点」等价于 d<r，也等价于直线与圆相交。"],["弧长公式 ★","n 为圆心角的度数，R 为半径，弧长 l 等于 n 度圆心角所对弧的长度。","公式中的 n 是圆心角的度数，不带单位「度」；分母是 180，不要与扇形面积公式的分母 360 混淆。由「整个圆的弧长 2π R 对应 360^°」可推出：l=(n)/(360)·2π R。求弧长前先确认 n 是圆心角而不是圆周角。"],["扇形面积公式 ★","n 为圆心角的度数，R 为半径，l 为该扇形的弧长，扇形面积等于 n 度圆心角所对扇形的面积。","两个公式都要记住：已知圆心角用前者，已知弧长用后者（形式与三角形面积公式类似，只是把「底」换成弧长 l、「高」换成半径 R）。分母是 360 不是 180；注意 R² 不要漏掉平方。"],["圆锥的侧面展开图与侧面积 ★","圆锥的侧面展开图是一个扇形：扇形的半径等于圆锥的母线长 l，扇形的弧长等于圆锥底面的周长 2π r；侧面积 S_侧=π rl，全面积 S=π rl+π r²。","求侧面展开图的圆心角时，用「底面周长等于扇形的弧长」列方程，可得 n=(360r)/(l)。扇形的半径是母线长 l，不是底面半径 r，两者混用是本条最常见的错误；已知母线长与底面半径即可求侧面积，不需要先求圆心角。"],["圆的周长与面积","圆的周长等于 2π R，圆的面积等于 π R²（R 为半径）。","这是弧长与扇形面积公式的来源。半圆的周长是 π R+2R（千万别漏掉直径 2R），半圆的面积是 (1)/(2)π R²；「圆的面积」与「周长」不要混用公式。"],["锐角三角函数的定义 ★","在 Rt△ ABC 中，∠ C=90^°，∠ A 的对边长为 a、邻边长为 b、斜边长为 c，则 ∠ A 的正弦、余弦、正切分别是「对边比斜边」「邻边比斜边」「对边比邻边」。","三角函数值只有在直角三角形中才能这样定义，所以做题时要先找（或构造）直角三角形。对边与邻边是相对某个锐角而言的：同一个三角形中，∠ A 的对边恰是 ∠ B 的邻边。因为斜边最长，所以 0<sin A<1，0<cos A<1；tan A>0 且随 A 增大而增大。"],["特殊角的三角函数值 ★","30^°、45^°、60^° 的正弦、余弦、正切值必须牢记。","记忆法：正弦依次为 (1)/(2)、√(2)2、√(3)2（分母都是 2，分子按 1,√(2),√(3) 递增），余弦正好相反；正切依次为 √(3)3、1、√(3)。tan30^°=√(3)3，不要错写成 (1)/(2) 或 √(3)2。这些值由 1,1,√(2) 与 1,√(3),2 型直角三角形直接得到。"],["同角三角函数的关系","同一个锐角的正弦与余弦的平方和等于 1；这个角的正切等于它的正弦与余弦的商。","适用条件是 ∠ A 为锐角（此时 sin A、cos A 都大于 0，cos A≠0）。书写上 sin²A 表示 (sin A)²，不是 sin(A²)。已知一个函数值求另外两个时，用这两个关系式或直接构造直角三角形（如 sin A=(3)/(5) 就取对边 3、斜边 5、邻边 4）都很快。"],["互余两角的三角函数关系","一个锐角的正弦等于它余角的余弦，这个角的余弦等于它余角的正弦；互为余角的两角的正切之积等于 1。","适用条件是 A 为锐角。由此可知 sin37^°=cos53^°，在含非特殊角的计算中常用来化简；已知 sin A=cos B（A、B 为锐角）可直接得到 A+B=90^°，这是「三角函数 + 直角三角形」结合题的常见突破口。"],["解直角三角形的基本关系 ★","在 Rt△ ABC 中（∠ C=90^°，∠ A、∠ B、∠ C 的对边分别为 a、b、c）：三边关系用勾股定理，两锐角互余，边角关系用三角函数。","三类关系（三边关系、锐角关系、边角关系）中「知二求三」：除直角外再知道两个元素（至少有一个是边）即可求出其余元素。选函数的口诀是「有斜用弦、无斜用切；宁乘勿除、取原避中」——尽量用已知量直接算所求量，避免经过中间量累积误差。"],["坡度（坡比）与坡角","坡面的铅直高度 h 与水平宽度 l 的比叫坡度（坡比），记作 i=(h)/(l)，它等于坡角 α 的正切。","坡度是「高度比水平宽度」，不是「高度比坡面长」（高度比坡面长是 sinα）。坡度常写成 1:m 的形式，此时 tanα=(1)/(m)；坡度越大坡越陡。解题时先把铅直高度与水平宽度标在图上，再选函数。"],["仰角、俯角与方向角","视线在水平线上方时，视线与水平线的夹角叫仰角；视线在水平线下方时，夹角叫俯角。方向角通常表述为「北偏东 α」「南偏西 α」等形式。","仰角、俯角都是视线与水平线的夹角，作图时必须先画出水平线。同一铅垂线上，从 A 处看 B 处的仰角与从 B 处看 A 处的俯角相等（两直线平行，内错角相等），这是解应用题的关键等量关系。解这类题先把实际问题翻译成「在一个或两个直角三角形中求边」。"]]},{"type":"note","title":"例题","text":"O 的半径为 5，弦 AB=5√(2)，点 C 在优弧 AB 上。求圆心 O 到弦 AB 的距离，并求 ∠ ACB 的度数。"},{"type":"figure","figure":{"id":"fig-m-for-yuan-e1","title":"连半径、作垂线求弦心距","caption":"OD⊥AB 于 D（D 处直角方框）：垂径定理给 AD=DB；点 C 在优弧 AB 上，∠ACB 是圆心角 ∠AOB 的一半","view":"square","alt":"圆 O 中有一条弦 AB，从圆心 O 向弦作垂线，垂足为 D，D 处画有直角方框；点 C 在另一段弧上，连接 CA、CB，图中标出圆心角 AOB 与圆周角 ACB。","prims":[{"t":"circle","cx":50,"cy":30,"r":26,"tone":"main"},{"t":"line","x1":31.6,"y1":48.4,"x2":68.4,"y2":48.4,"width":0.8},{"t":"line","x1":50,"y1":30,"x2":50,"y2":48.4,"tone":"accent"},{"t":"line","x1":50,"y1":30,"x2":31.6,"y2":48.4,"tone":"muted","dashed":true},{"t":"line","x1":50,"y1":4,"x2":31.6,"y2":48.4,"tone":"accent"},{"t":"line","x1":50,"y1":4,"x2":68.4,"y2":48.4,"tone":"accent"},{"t":"line","x1":46.5,"y1":48.4,"x2":46.5,"y2":44.9,"tone":"muted"},{"t":"line","x1":46.5,"y1":44.9,"x2":50,"y2":44.9,"tone":"muted"},{"t":"angle","x":50,"y":30,"from":-135,"to":-45,"r":9,"tone":"accent","label":"∠AOB"},{"t":"angle","x":50,"y":4,"from":-112.51,"to":-67.49,"r":8,"tone":"danger","label":"∠ACB"},{"t":"text","x":56,"y":38,"text":"OD = ?","anchor":"start","size":3.6,"tone":"danger"},{"t":"dot","x":50,"y":30,"label":"O","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":31.6,"y":48.4,"label":"A","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":68.4,"y":48.4,"label":"B","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":50,"y":4,"label":"C","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":50,"y":48.4,"label":"D","labelDx":2.2,"labelDy":-2.6}]}},{"type":"list","title":"解题步骤","items":["作 OD⊥ AB 于 D：这满足垂径定理的条件（OD 是弦心距所在的直线），于是 AD=DB=(1)/(2)AB=5√(2)2。","在 Rt△ OAD 中用勾股定理求弦心距：OD=√(OA²-AD²)=√(25-(25)/(2))=5√(2)2。","因为 OD=AD=5√(2)2，所以 △ OAD 是等腰直角三角形，∠ AOD=45^°，由对称性得圆心角 ∠ AOB=2∠ AOD=90^°。","点 C 在优弧 AB 上，∠ ACB 所对的是不含点 C 的弧 AB，由圆周角定理得 ∠ ACB=(1)/(2)∠ AOB=45^°。"]},{"type":"p","text":"答案：圆心 O 到弦 AB 的距离为 5√(2)2，∠ ACB=45^°"},{"type":"note","title":"方法小结","text":"圆中求弦长、弦心距的固定动作是「连半径、作垂线」，把条件集中到一个直角三角形里用勾股定理（R²=d²+((a)/(2))²）；再由「同弧所对的圆周角等于圆心角的一半」求角，务必看清点在哪一段弧上、角所对的是哪条弧。"},{"type":"note","title":"例题","text":"如图，PA、PB 分别切 O 于点 A、B，∠ APB=60^°，O 的半径为 3。求切线长 PA。"},{"type":"figure","figure":{"id":"fig-m-for-yuan-1","title":"从圆外一点引圆的两条切线","caption":"PA=PB，OP 平分 ∠APB，OA⊥PA，OB⊥PB","view":"wide","alt":"圆 O 右侧有一点 P，从 P 引出两条切线分别与圆相切于上方的点 A 和下方的点 B；连接 OA、OB、OP，OA 垂直于 PA，OB 垂直于 PB，∠APB 标为 60 度","prims":[{"t":"circle","cx":50,"cy":50,"r":22},{"t":"line","x1":86,"y1":50,"x2":59,"y2":34,"width":1.8},{"t":"line","x1":86,"y1":50,"x2":59,"y2":66,"width":1.8},{"t":"line","x1":50,"y1":50,"x2":59,"y2":34,"tone":"muted"},{"t":"line","x1":50,"y1":50,"x2":59,"y2":66,"tone":"muted"},{"t":"line","x1":50,"y1":50,"x2":86,"y2":50,"dashed":true,"tone":"muted"},{"t":"angle","x":59,"y":34,"from":240,"to":330,"right":true,"r":5,"tone":"muted"},{"t":"angle","x":59,"y":66,"from":30,"to":120,"right":true,"r":5,"tone":"muted"},{"t":"angle","x":86,"y":50,"from":149,"to":211,"r":11,"label":"60°","tone":"accent"},{"t":"dot","x":50,"y":50,"r":1.2},{"t":"text","x":46,"y":57,"text":"O","size":4,"anchor":"end"},{"t":"text","x":90,"y":52,"text":"P","size":4,"anchor":"start"},{"t":"text","x":59,"y":29,"text":"A","size":4,"anchor":"middle"},{"t":"text","x":59,"y":72,"text":"B","size":4,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["由切线长定理，PA=PB，且点 P 与圆心 O 的连线平分两条切线的夹角，所以 ∠ APO=(1)/(2)∠ APB=30^°。","由切线的性质，圆的切线垂直于过切点的半径，所以 OA⊥ PA，即 ∠ OAP=90^°，△ OAP 是直角三角形。","在 Rt△ OAP 中，tan 30^°=(OA)/(PA)，故 PA=(OA)/(tan 30^°)=3√(3)3=3√(3)。","也可验证：30^° 角所对的直角边 OA 等于斜边 OP 的一半，OP=6，再由勾股定理得 PA=√(6²-3²)=3√(3)。"]},{"type":"p","text":"答案：切线长 PA=3√(3)。"},{"type":"note","title":"方法小结","text":"看到圆外一点引两条切线，先想到切线长定理：切线长相等、连线平分夹角；再连切点半径得到直角三角形，用三角函数或勾股定理求长度。"},{"type":"note","title":"例题","text":"如图，某人在水平地面上的点 A 处测得塔顶 C 的仰角为 30^°，沿正对塔的方向前进 60 m 到达点 B，在 B 处测得塔顶 C 的仰角为 60^°。已知塔底 D 与 A、B 在同一直线上，塔 CD 垂直于地面，测量者身高忽略不计，求塔高 CD。"},{"type":"figure","figure":{"id":"fig-m-for-yuan-2","title":"两次仰角测塔高","caption":"在 A 处仰角 30°，前进 60 m 到 B 处仰角 60°，求塔高 CD","view":"wide","alt":"水平地面上从左到右依次是点 A、点 B 和塔底 D，塔 CD 竖直向上，塔顶为 C；从 A 到 C 的视线与水平线夹角为 30 度，从 B 到 C 的视线与水平线夹角为 60 度，AB 段标为 60 m","prims":[{"t":"line","x1":12,"y1":80,"x2":90,"y2":80,"tone":"muted"},{"t":"line","x1":70,"y1":80,"x2":70,"y2":59,"width":2.5,"tone":"main"},{"t":"line","x1":34,"y1":80,"x2":70,"y2":59,"tone":"accent"},{"t":"line","x1":58,"y1":80,"x2":70,"y2":59,"tone":"accent"},{"t":"line","x1":34,"y1":80,"x2":66,"y2":80,"dashed":true,"tone":"muted"},{"t":"line","x1":58,"y1":80,"x2":70,"y2":80,"dashed":true,"tone":"muted"},{"t":"angle","x":34,"y":80,"from":0,"to":30,"r":11,"label":"30°","tone":"accent"},{"t":"angle","x":58,"y":80,"from":0,"to":60,"r":11,"label":"60°","tone":"accent"},{"t":"angle","x":70,"y":80,"from":90,"to":180,"right":true,"r":5,"tone":"muted"},{"t":"text","x":34,"y":85,"text":"A","size":4,"anchor":"middle"},{"t":"text","x":58,"y":85,"text":"B","size":4,"anchor":"middle"},{"t":"text","x":70,"y":85,"text":"D","size":4,"anchor":"middle"},{"t":"text","x":70,"y":55,"text":"C","size":4,"anchor":"middle"},{"t":"text","x":46,"y":76,"text":"60 m","size":3.2,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["设塔高 CD=h m。CD⊥ AD，所以 △ ACD、△ BCD 都是直角三角形，且 AD-BD=AB=60。","在 Rt△ ACD 中，tan 30^°=(h)/(AD)，所以 AD=(h)/(tan 30^°)=√(3)h。","在 Rt△ BCD 中，tan 60^°=(h)/(BD)，所以 BD=(h)/(tan 60^°)=h√(3)。","由 AD-BD=60 列方程：√(3)h-h√(3)=60，即 h(√(3)-1√(3))=2h√(3)=60，解得 h=30√(3)。"]},{"type":"p","text":"答案：塔高 CD 为 30√(3) m。"},{"type":"note","title":"方法小结","text":"两次仰角测高的关键是用塔高 h 表示两个水平距离，再利用「前进的距离等于两个水平距离之差」列方程；仰角的对边都是塔高，邻边一长一短，不要写反。"},{"type":"list","title":"易错点","items":["切线的判定只写「垂直于半径」而漏掉「经过半径的外端」；用切线性质时忘记先连接圆心与切点得到半径。","把圆周角与圆心角的关系写成 2 倍（应为圆周角等于圆心角的一半）；忘记「直径所对的圆周角是直角」这一常用结论。","弧长与扇形面积公式混用分母（弧长是 $180$、扇形面积是 $360$），或把 $R^2$ 写成 $R$。","圆锥问题中把底面半径当成展开图扇形的半径（扇形的半径是母线长），求圆心角时不列「底面周长等于扇形弧长」的方程。"]},{"type":"list","title":"解题方法","items":["圆中「连半径、作垂线」是万能第一步：垂径定理、切线性质、圆周角定理都靠这两条辅助线把条件集中到直角三角形里，再接勾股定理或三角函数。","三角函数计算遵循「有斜用弦、无斜用切；宁乘勿除、取原避中」：已知斜边用正弦或余弦，没有斜边用正切，尽量用已知量直接算所求量。","解直角三角形的应用题按四步走：画示意图并标出已知的边、角（仰角俯角、坡角、方向角都要先画出水平线）→ 找出或构造直角三角形 → 选合适的三角函数列式 → 检验结果是否符合实际（长度为正、角度与图形一致）。"]}],"questions":[{"id":"q-m-for-yuan-1","type":"choice","stem":"若 O 的半径为 5，圆心 O 到弦 AB 的距离为 3，则弦 AB 的长为","answer":"C","explain":"设 OD⊥ AB 于 D，由垂径定理得 AD=(1)/(2)AB。在 Rt△ OAD 中，AD=√(OA²-OD²)=√(25-9)=4，所以 AB=2AD=8。选项 A 是半弦长，容易误选。","options":["4","6","8","10"],"difficulty":2,"tags":["垂径定理","勾股定理"],"figure":{"id":"fig-m-for-yuan-q1","title":"半径、弦心距与半弦","caption":"半径 OA=5、弦心距 OD=3：在 Rt△OAD 中由勾股定理求 AD，再乘 2 得弦 AB","view":"wide","alt":"圆 O 中有弦 AB，圆心 O 到弦 AB 的垂线段 OD 长为 3，半径 OA 长为 5；D 处画有直角方框，弦 AB 的长度待求。","prims":[{"t":"circle","cx":50,"cy":30,"r":26,"tone":"main"},{"t":"line","x1":29.2,"y1":45.6,"x2":70.8,"y2":45.6,"width":0.8},{"t":"line","x1":50,"y1":30,"x2":50,"y2":45.6,"tone":"accent"},{"t":"line","x1":50,"y1":30,"x2":29.2,"y2":45.6,"tone":"muted","dashed":true},{"t":"line","x1":46.5,"y1":45.6,"x2":46.5,"y2":42.1,"tone":"muted"},{"t":"line","x1":46.5,"y1":42.1,"x2":50,"y2":42.1,"tone":"muted"},{"t":"text","x":35,"y":32,"text":"OA = 5","anchor":"end","size":3.6,"tone":"muted"},{"t":"text","x":53,"y":37,"text":"OD = 3","anchor":"start","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":55,"text":"AB = ?","anchor":"middle","size":3.6,"tone":"danger"},{"t":"dot","x":50,"y":30,"label":"O","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":29.2,"y":45.6,"label":"A","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":70.8,"y":45.6,"label":"B","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":50,"y":45.6,"label":"D","labelDx":2.2,"labelDy":-2.6}]}},{"id":"q-m-for-yuan-2","type":"fill","stem":"若 ∠ A 为锐角，且 sin A=(3)/(5)，则 cos A 的值是____。","answer":"4/5","explain":"方法一：由 sin²A+cos²A=1 得 cos²A=1-(9)/(25)=(16)/(25)，因为 ∠ A 为锐角，cos A>0，所以 cos A=(4)/(5)。方法二：构造直角三角形，∠ A 的对边为 3、斜边为 5，则邻边为 √(5²-3²)=4，故 cos A=(4)/(5)。","difficulty":2,"tags":["同角三角函数关系"],"figure":{"id":"fig-for-sanjiao-sin","title":"由正弦值构造直角三角形","caption":"sin A = 3/5 可看作 ∠A 的对边为 3、斜边为 5：先用勾股定理求出邻边为 4，再读 cos A 与 tan A","view":"wide","alt":"直角三角形 ABC，顶点 C 处画有直角方框，顶点 A 处标出角 A；角 A 的对边标注为 3、邻边标注为 4、斜边标注为 5，旁边写着 sin A 等于 3 比 5。","prims":[{"t":"poly","points":[[80,54],[20,16],[20,54]],"closed":true},{"t":"line","x1":24,"y1":54,"x2":24,"y2":50,"tone":"muted"},{"t":"line","x1":24,"y1":50,"x2":20,"y2":50,"tone":"muted"},{"t":"angle","x":80,"y":54,"from":147.65,"to":180,"r":9,"tone":"ok","label":"∠A"},{"t":"text","x":16,"y":36,"text":"对边 3","anchor":"end","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"邻边 4","anchor":"middle","size":3.6,"tone":"muted"},{"t":"text","x":54,"y":30,"text":"斜边 5","anchor":"start","size":3.6,"tone":"muted"},{"t":"text","x":84,"y":16,"text":"sin A = 3/5","anchor":"end","size":3.6,"tone":"accent"},{"t":"dot","x":80,"y":54,"label":"A","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":20,"y":16,"label":"B","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":20,"y":54,"label":"C","labelDx":2.2,"labelDy":-2.6}]}},{"id":"q-m-for-yuan-3","type":"choice","stem":"半径为 6、圆心角为 120^° 的弧长是","answer":"B","explain":"由弧长公式 l=(nπ R)/(180)=(120π×6)/(180)=4π。C 是直接用 π R 的错误算法，D 是把分母当成 90 的结果。","options":["2π","4π","6π","12π"],"difficulty":1,"tags":["弧长公式"]},{"id":"q-m-for-yuan-4","type":"short","stem":"已知圆锥的底面半径为 3，母线长为 6，求它的侧面展开图的圆心角以及圆锥的侧面积。","answer":"底面周长为 $2\\pi r=2\\pi\\times3=6\\pi$，它等于侧面展开图扇形的弧长。由 $6\\pi=\\frac{n\\pi\\times6}{180}$ 解得 $n=180$，即圆心角为 $180^\\circ$。扇形的半径等于母线长 $l=6$，所以侧面积 $S_{\\text{侧}}=\\pi rl=\\pi\\times3\\times6=18\\pi$。","explain":"关键是把圆锥的侧面展开成扇形：扇形半径是母线长 6（不是底面半径 3），扇形弧长等于底面周长 6π。由弧长公式反解圆心角得 n=180^°（也可用 n=(360r)/(l)=(360×3)/(6)=180）。侧面积用 S_侧=π rl 直接得 18π，不需要先求圆心角。","difficulty":2,"tags":["圆锥侧面积","弧长公式"],"rubric":["算出底面周长 2π r=6π，并说明它等于展开图扇形的弧长","由 6π=(nπ·6)/(180) 正确解得圆心角 n=180^°","指出扇形的半径为母线长 6，不是底面半径 3","用 S_侧=π rl 得出侧面积 18π（保留 π）"]},{"id":"q-m-for-yuan-z1","type":"choice","stem":"如图，△ ABC 内接于 O，AB 是 O 的直径，∠ A=35^°，则 ∠ B 的度数为","answer":"C","explain":"因为 AB 是直径，直径所对的圆周角是直角，所以 ∠ C=90^°。直角三角形的两个锐角互余，故 ∠ B=90^°-∠ A=90^°-35^°=55^°。","options":["35^°","45^°","55^°","65^°"],"difficulty":2,"tags":["圆周角定理","直径所对圆周角"],"figure":{"id":"fig-m-for-yuan-z1","title":"直径所对的圆周角是直角","caption":"AB 为直径，故 ∠C=90°，∠A 与 ∠B 互余","view":"wide","alt":"圆 O 内接三角形 ABC，AB 是水平直径，点 C 在圆上位于 AB 上方；∠A 标为 35 度，∠C 处标有直角符号，表示直径所对的圆周角为直角","prims":[{"t":"circle","cx":50,"cy":50,"r":30},{"t":"line","x1":20,"y1":50,"x2":80,"y2":50,"tone":"main"},{"t":"line","x1":20,"y1":50,"x2":60,"y2":22,"tone":"main"},{"t":"line","x1":80,"y1":50,"x2":60,"y2":22,"tone":"main"},{"t":"angle","x":20,"y":50,"from":0,"to":-35,"r":9,"label":"35°","tone":"accent"},{"t":"angle","x":60,"y":22,"from":215,"to":305,"right":true,"r":6,"tone":"muted"},{"t":"dot","x":50,"y":50,"r":1.2,"tone":"muted"},{"t":"text","x":16,"y":53,"text":"A","size":4,"anchor":"end"},{"t":"text","x":84,"y":53,"text":"B","size":4,"anchor":"start"},{"t":"text","x":60,"y":17,"text":"C","size":4,"anchor":"middle"},{"t":"text","x":50,"y":57,"text":"O","size":3.4,"anchor":"middle","tone":"muted"}]}},{"id":"q-m-for-yuan-z2","type":"short","stem":"一个扇形的半径为 4，圆心角为 90^°。求这个扇形的弧长和面积（结果保留 π）。","answer":"弧长 $l=\\frac{n\\pi R}{180}=\\frac{90\\pi\\times 4}{180}=2\\pi$；扇形面积 $S=\\frac{n\\pi R^2}{360}=\\frac{90\\pi\\times 4^2}{360}=4\\pi$。","explain":"弧长公式分母为 180，扇形面积公式分母为 360，二者不要混用；面积公式中是半径的平方 R²，不能写成 R。本题也可用 S=(1)/(2)lR=(1)/(2)× 2π× 4=4π 检验，结果一致。","difficulty":2,"tags":["弧长公式","扇形面积"],"rubric":["正确代入弧长公式，得弧长 l=2π","正确代入扇形面积公式（注意 R² 与分母 360），得面积 S=4π","结果保留 π，并写清弧长与面积两个量"]}]}];
